  if exists (select 1 from spaces where slug = 'hq' and owner_profile_id is distinct from '78d47bae-c4c8-4d1c-80a0-ac69aaf98ef8') then
    raise exception 'seed-frequency-hosts: the slug hq belongs to someone else; nothing written';
  end if;
end $guard$;

