values ('9e17060e-63ca-6dcc-abc1-8fa9edb280e7', 'hq', 'Frequency', 'business', 'active', (select entity_id from spaces where type = 'root' order by created_at limit 1), 'dawn', true, 'network', 'collective', true, true, '{}'::jsonb, '78d47bae-c4c8-4d1c-80a0-ac69aaf98ef8', 'Frequency', '#1AA7C0', 'Gather like it matters.', 'This is the Frequency team''s own Space: the home base for everyone building Frequency. Find our programs, take free host training on the PULSE rhythm, learn to run your community in Creator Lab, get help from a real person, and ask the community in the forum.', 'America/Los_Angeles', '/brand/frequency/logo/frequency-icon-round.png', '/brand/frequency/photos/day-meditation-circle.jpg', '{"theme":"modern","siteStyle":{"theme":"new-world","synced":true,"spaceFonts":"modern"},"megaTheme":{"theme":"new-world","niche":"networks"},"pages":[{"slug":"home","label":"Home","system":true},{"slug":"programs","label":"Programs"},{"slug":"creator-lab","label":"Creator Lab"},{"slug":"business-of-community","label":"Business of Community"},{"slug":"help","label":"Help desk"},{"slug":"about","label":"About"}],"pageDocs":{"home":{"root":{"props":{}},"content":[{"type":"NewWorldHero","props":{"id":"fh-home-hero-0","eyebrow":"Frequency · Programs, training and help","title":"Gather like it *matters.*","lead":"The home base for everyone building Frequency. Find our programs, learn to host on the PULSE rhythm, get help from a real person, and ask the community anything. Start wherever you are.","primaryLabel":"Explore programs","primaryHref":"/spaces/hq/programs","secondaryLabel":"Get help","secondaryHref":"/spaces/hq/help","proof":"Run by the Frequency team, for members, hosts and Spaces.","aside":"We build circles, not walls.","image":"/brand/frequency/photos/day-meditation-circle.jpg","alt":"A large circle of people seated on the grass by the ocean, eyes closed","badge":"Open to everyone","useEvents":true,"rows":[{"weekday":"Help","mon":"Desk","day":"1","title":"Open a help ticket","body":"A real person reads every ticket.","time":"Any time","where":"Online","spots":"Open","kind":"session","href":"/support"},{"weekday":"Workshop","mon":"Free","day":"2","title":"The Business of Community","body":"A free four-week live workshop on the PULSE rhythm. Starts January 7.","time":"4 weeks · live on Zoom","where":"Online","spots":"Open","kind":"session","href":"/events/business-of-community-pilot-session-1"},{"weekday":"Course","mon":"Free","day":"3","title":"Host Foundations","body":"Four short weeks on the craft every Frequency host shares: why we gather, the PULSE rhythm, setting the room, and running your first circle.","time":"Self-paced · 4 parts","where":"Online","spots":"Open","kind":"session","href":"/journeys/host-foundations"}],"register":"auto"}},{"type":"NewWorldStats","props":{"id":"fh-home-stats-1","items":[{"icon":"heart","value":"4","label":"Pillars","note":"Mind, Body, Spirit, Expression"},{"icon":"users","value":"5","label":"beats in every circle","note":"Presence, Unite, Lead, Settle, Exhale"},{"icon":"calendar","value":"4","label":"host courses","note":"Three free online, one in person"},{"icon":"check","value":"1","label":"help desk","note":"A real person answers"}],"register":"auto"}},{"type":"NewWorldPromises","props":{"id":"fh-home-doors-2","index":"01","eyebrow":"Inside","title":"Five *doors.*","lede":"Everything the Frequency team runs for members, hosts and Spaces.","rows":[{"icon":"award","title":"Programs","body":"The Quest, Circles, events and host training: the structured ways to take part."},{"icon":"heart","title":"Host training","body":"Free courses on the PULSE rhythm, care and consent, and the three circle formats."},{"icon":"check","title":"Help desk","body":"Open a ticket, browse the help center, or report something that feels off."},{"icon":"sparkle","title":"Creator Lab","body":"Business and leadership for the people who gather others. Starts with The Business of Community 101."},{"icon":"users","title":"Community forum","body":"Ask a question, share what worked, suggest a feature. Hosts and the team read it."}],"register":"auto"}},{"type":"NewWorldStory","props":{"id":"fh-home-story-3","index":"02","eyebrow":"A community collective","title":"Built by *its members.*","paragraphs":["Frequency is a community collective, not just an app. The software helps people find each other and helps local hosts and businesses run their rooms. The point is the room.","We grow town by town, one circle at a time. Every one of those circles needs someone who arrives early, sets the chairs, starts on time and makes the new person feel expected.","This Space is where that work is shared in the open: the programs, the training, the answers and the conversation."],"buttonLabel":"Our story","buttonHref":"/spaces/hq/about","secondaryLabel":"Ask the community","secondaryHref":"/spaces/hq/community","image":"/brand/frequency/photos/gathering-03.jpg","alt":"People gathered on rugs and cushions in a leafy garden","quote":"The structure exists to serve the circle.","quoteBy":"Daniel Tyack · Founder","register":"auto"}},{"type":"SpacePractices","props":{"id":"fh-home-journeys-4","eyebrow":"Learn here","heading":"Courses to start","practicesHeading":"Practices","journeysHeading":"Courses","only":""}},{"type":"NewWorldProcess","props":{"id":"fh-home-path-5","index":"03","eyebrow":"Host training","title":"From guest to *host.*","lede":"","rows":[{"icon":"calendar","title":"Learn","body":"Take Host Foundations, free and self-paced. Four short weeks on the PULSE rhythm."},{"icon":"heart","title":"Learn to care","body":"Take Safe and Well Held: agreements, consent and what to do when something comes up."},{"icon":"users","title":"Co-host","body":"Run two circles beside a trained host. Lead one beat, then two, then the whole night."},{"icon":"award","title":"Host","body":"Open your own circle with a mentor on call, then join the monthly Host Circle."}],"register":"auto"}},{"type":"NewWorldGallery","props":{"id":"fh-home-gallery-6","index":"04","eyebrow":"Real circles","title":"Rooms people *come back to.*","lede":"Photos from Frequency gatherings.","images":[{"image":"/brand/frequency/photos/gathering-04.jpg","alt":"A circle seated on a lawn with arms stretched wide"},{"image":"/brand/frequency/photos/gathering-12.jpg","alt":"A tight group hugging and laughing on a seaside deck"},{"image":"/brand/frequency/photos/day-parachute-play.jpg","alt":"People holding a rainbow parachute on a clifftop lawn"},{"image":"/brand/frequency/photos/gathering-14.jpg","alt":"A circle on mats around a gong at the water"},{"image":"/brand/frequency/photos/gathering-13.jpg","alt":"A group moving together on the beach at golden hour"}],"register":"auto"}},{"type":"NewWorldFaq","props":{"id":"fh-home-faq-7","index":"05","eyebrow":"Questions","title":"Good to *know.*","lede":"Anything else, ask. A real person answers.","phone":"","email":"hello@frequencylocal.com","hours":"","areasLabel":"","areas":[],"rows":[{"question":"What is this Space?","answer":"The Frequency team''s own Space: our programs, host training, Creator Lab, the help desk and a community forum, in one place. Follow it to hear what''s new."},{"question":"How do I get help with my account?","answer":"Open a help ticket from the help desk. A real person reads every one, and you can follow the reply from your tickets."},{"question":"Do I need experience to host?","answer":"No. Most Frequency hosts started as guests. Host Foundations and the apprenticeship take you from your first seat in the circle to running your own."},{"question":"Can my organization train its own hosts here?","answer":"Yes. The courses and the PULSE rhythm are built so partner organizations and volunteers can use them for their own in-person and online groups."},{"question":"Where do I ask other members a question?","answer":"In the community forum. Post a question, share what worked, or say hello. Hosts and the team read it too."}],"register":"auto"}},{"type":"NewWorldCloser","props":{"id":"fh-closer-home-8","aside":"Generous structure. Real care. On time.","title":"Pick a door. *Come in.*","primaryLabel":"Ask the community","primaryHref":"/spaces/hq/community","secondaryLabel":"Get help","secondaryHref":"/support","note":"","register":"auto"}}]},"programs":{"root":{"props":{}},"content":[{"type":"NewWorldPageHead","props":{"id":"fh-programs-head-9","index":"","eyebrow":"Frequency Programs","title":"Show up. *Come back.*","lede":"Frequency Programs are the structured ways to take part: The Quest, Circles, local events and host training. Start with one.","register":"auto"}},{"type":"NewWorldWayRows","props":{"id":"fh-programs-rows-a","costLabel":"For","whenLabel":"Rhythm","buttonLabel":"Start","buttonHref":"/circles","secondaryLabel":"Questions","secondaryHref":"/spaces/hq/help","rows":[{"icon":"award","tags":"Program","name":"The Quest","body":"Daily practices and Journeys you take with your Circle, across the four Pillars. Show up, earn Zaps and Gems, and climb the season.","price":"Every member","when":"Daily","image":"/brand/frequency/photos/gathering-13.jpg","alt":"A group moving together on the beach at golden hour","buttonLabel":"How The Quest works","href":"/help/the-quest"},{"icon":"users","tags":"Program","name":"Circles","body":"Small groups of 12 to 18 people who meet at the same time in the same place, on the PULSE rhythm.","price":"Every member","when":"Weekly or every other week","image":"/brand/frequency/photos/gathering-04.jpg","alt":"A circle seated on a lawn with arms stretched wide","buttonLabel":"Find a Circle","href":"/circles"},{"icon":"calendar","tags":"Program","name":"What''s happening","body":"Local events from Circles and Spaces near you. RSVP, add it to your calendar, bring someone.","price":"Everyone","when":"Any week","image":"/brand/frequency/photos/day-parachute-play.jpg","alt":"People holding a rainbow parachute on a clifftop lawn","buttonLabel":"See what''s happening","href":"/events"},{"icon":"sparkle","tags":"Program","name":"Creator Lab","body":"Core training for the people who gather others. The Business of Community is a free four-week live workshop on Zoom, run several times a year; the Business plan adds Business Hours on Zoom.","price":"Anyone","when":"One week at a time","image":"/brand/frequency/photos/gathering-03.jpg","alt":"People gathered on rugs and cushions in a leafy garden","buttonLabel":"Open Creator Lab","href":"/spaces/hq/creator-lab"},{"icon":"heart","tags":"Program","name":"Host training","body":"Free courses on the PULSE rhythm, care and consent, and the three circle formats, then a co-host apprenticeship.","price":"Hosts and future hosts","when":"Self-paced","image":"/brand/frequency/photos/day-meditation-circle.jpg","alt":"A large circle of people seated on the grass by the ocean, eyes closed","buttonLabel":"Start host training","href":"/spaces/hq/creator-lab"}],"register":"auto"}},{"type":"NewWorldPromises","props":{"id":"fh-programs-pillars-b","index":"01","eyebrow":"The Quest","title":"Four *Pillars.*","lede":"Every practice and Journey sits under one Pillar, so you build the same strengths all year in different forms.","rows":[{"icon":"sparkle","title":"Mind","body":"Calm down fast, focus, and think clearly. Practices like breathing, journaling and less scrolling."},{"icon":"heart","title":"Body","body":"Move, rest, eat and sleep like you mean it. Walks, stretching, cold water, early nights."},{"icon":"users","title":"Spirit","body":"Meaning, gratitude and time with people. Stillness, service and showing up for each other."},{"icon":"award","title":"Expression","body":"Make something and share it. The weekly Expression Challenge, alone or with your Circle."}],"register":"auto"}},{"type":"NewWorldProcess","props":{"id":"fh-programs-quest-c","index":"02","eyebrow":"How The Quest works","title":"Small things, *every day.*","lede":"","rows":[{"icon":"calendar","title":"Pick a Journey","body":"Choose one under a Pillar. Each has a few minutes of practice a day."},{"icon":"check","title":"Practice daily","body":"Log it when you do it. Streaks build, and misses are part of it."},{"icon":"users","title":"Bring your Circle","body":"Take a Journey with your Circle and show up for each other in person."},{"icon":"award","title":"Earn as you go","body":"Zaps and Gems for showing up, a Pillar Trophy when you finish a Journey."}],"register":"auto"}},{"type":"NewWorldCloser","props":{"id":"fh-closer-programs-d","aside":"Generous structure. Real care. On time.","title":"Start with *one.*","primaryLabel":"Find a Circle","primaryHref":"/circles","secondaryLabel":"See what''s happening","secondaryHref":"/events","note":"","register":"auto"}}]},"creator-lab":{"root":{"props":{}},"content":[{"type":"NewWorldPageHead","props":{"id":"fh-lib-head-14","index":"","eyebrow":"Creator Lab","title":"Courses for the people who *gather others.*","lede":"Free courses in two tracks: hosting the room, and running the community behind it. Start anywhere. Every course ends with you doing it for real.","register":"auto"}},{"type":"NewWorldPromises","props":{"id":"fh-lib-tracks-15","index":"01","eyebrow":"The library","title":"Two *tracks.*","lede":"Each course is free. The Business plan adds a weekly room on Zoom.","rows":[{"icon":"heart","title":"Hosting","body":"The PULSE rhythm, care and consent, the three circle formats, and an apprenticeship beside a trained host."},{"icon":"sparkle","title":"Business and leadership","body":"The Business of Community: four simple meetings on PULSE that bring people back, and keep you going."}],"register":"auto"}},{"type":"NewWorldWayRows","props":{"id":"fh-lib-rows-16","costLabel":"Cost","whenLabel":"Length","buttonLabel":"Start a course","buttonHref":"/spaces/hq/business-of-community","secondaryLabel":"Questions","secondaryHref":"/spaces/hq/help","rows":[{"icon":"calendar","tags":"Business · 4 weeks","name":"The Business of Community","body":"Frequency’s free live workshop. Four 90-minute sessions on Zoom, all on PULSE: the weekly sit-down, the opening, the full gathering and the money hour. Short lessons to read before each one.","price":"Free","when":"4 weeks","image":"/brand/frequency/photos/gathering-04.jpg","alt":"A circle seated on a lawn with arms stretched wide","buttonLabel":"See the workshop","href":"/spaces/hq/business-of-community"},{"icon":"users","tags":"Business · January Run","name":"The January Run","body":"Everyone in the launch Run, together. A thread to share what you tried between sessions, and someone noticing when you don’t show. Thursdays Jan 7, 14, 21 and 28.","price":"Free","when":"Starts January 7","image":"/brand/frequency/photos/gathering-12.jpg","alt":"A tight group hugging and laughing on a seaside deck","buttonLabel":"Join the Run","href":"/circles/business-of-community-january-2027"},{"icon":"message","tags":"Business · Zoom","name":"Business Hours","body":"Same hour every week, run on PULSE. Bring one number and one stuck thing. Last week’s commitments read back, one hot seat, and a new commitment each.","price":"Business plan","when":"Wednesdays · 10 AM Pacific","image":"/sites/new-world/photos/cafe-table.webp","alt":"Three people talking at a small table in a cafe","buttonLabel":"See the Circle","href":"/circles/business-hours"},{"icon":"calendar","tags":"Hosting · Online","name":"Host Foundations","body":"Four short weeks on the craft every Frequency host shares: why we gather, the PULSE rhythm, setting the room, and running your first circle.","price":"Free","when":"4 parts","image":"/brand/frequency/photos/day-meditation-circle.jpg","alt":"","buttonLabel":"Start the course","href":"/journeys/host-foundations"},{"icon":"heart","tags":"Hosting · Online","name":"Safe and Well Held","body":"Agreements, consent and care: how to keep a room safe enough to be honest, and what to do when something comes up.","price":"Free","when":"4 parts","image":"/brand/frequency/photos/gathering-12.jpg","alt":"","buttonLabel":"Start the course","href":"/journeys/safe-and-well-held"},{"icon":"users","tags":"Hosting · Online","name":"The Three Circle Formats","body":"Open, Community and Focus Circles: what each one is for, what the host does, and how to choose.","price":"Free","when":"4 parts","image":"/brand/frequency/photos/gathering-03.jpg","alt":"","buttonLabel":"Start the course","href":"/journeys/circle-formats"},{"icon":"award","tags":"Hosting · In person","name":"Co-host Apprenticeship","body":"Learn by doing: shadow a trained host, co-lead two circles, then host your own with a mentor on call.","price":"Ask us","when":"Three circles","image":"/brand/frequency/photos/gathering-04.jpg","alt":"","buttonLabel":"Ask about a mentor","href":"/journeys/co-host-apprenticeship"}],"register":"auto"}},{"type":"NewWorldProcess","props":{"id":"fh-pulse-beats-h","index":"02","eyebrow":"The PULSE rhythm · for everyone","title":"What each beat *is.*","lede":"","rows":[{"icon":"heart","title":"P · Presence","body":"Arrive. A few slow breaths, feet on the floor, phones away. The host sets the tone by going first."},{"icon":"users","title":"U · Unite","body":"A check-in round. Each person says how they''re arriving, and everyone else listens without replying."},{"icon":"award","title":"L · Lead","body":"Tonight''s practice: a teaching, a movement, a conversation or a skill. The part that changes from week to week."},{"icon":"check","title":"S · Settle","body":"Quiet integration. Rest, journal or sit with what came up before anyone has to talk about it."},{"icon":"message","title":"E · Exhale","body":"Close together. One word or one line each, a thank you, and a clear end."}],"register":"auto"}},{"type":"NewWorldFirstVisit","props":{"id":"fh-pulse-host-i","index":"03","eyebrow":"The PULSE rhythm · for the host","title":"What you *do.*","lede":"A 90-minute night, beat by beat.","note":"Shorter night? Trim Lead first. Never skip Exhale.","rows":[{"title":"Presence · 10 min","body":"Start on time. Welcome people by name. Name the purpose of tonight in one sentence."},{"title":"Unite · 20 min","body":"Read the agreements. Ask one question everyone can answer. Keep it lean so everyone gets a turn."},{"title":"Lead · 35 min","body":"Give clear steps, an invitation and an opt-out. Watch the room more than your notes."},{"title":"Settle · 15 min","body":"Lower the pace. Offer a simple prompt. Let silence do some of the work."},{"title":"Exhale · 10 min","body":"End on time. Say what happens next and how people can reach you."}],"register":"auto"}},{"type":"NewWorldPromises","props":{"id":"fh-training-formats-j","index":"04","eyebrow":"One rhythm","title":"Three *formats.*","lede":"Every circle runs on PULSE. The format decides how much you teach and how big the room gets.","rows":[{"icon":"users","title":"Open Circle · 12 to 18 people","body":"The host keeps the room, with no teaching agenda. People come to be heard and to hear each other. You open and close, keep the agreements and the time, and pass the turn. You speak least."},{"icon":"heart","title":"Community Circle · 12 to 18 people","body":"A hosted circle around one shared theme: moon circles, men''s and women''s circles, grief, new parents, sharing circles. You choose the theme and the question for the round, and keep the circle on it."},{"icon":"award","title":"Focus Circle · Up to 50 people","body":"The host teaches a modality: breathwork, sound, movement, a skill. The PULSE rhythm wraps the teaching so the room still feels like a circle. You teach in the Lead beat, and the four beats around it keep it personal and safe."}],"register":"auto"}},{"type":"NewWorldPromises","props":{"id":"fh-training-agreements-k","index":"05","eyebrow":"Read at every circle","title":"Six *agreements.*","lede":"","rows":[{"icon":"check","title":"Every practice is an invitation","body":"Join in, go gently, watch, or pass. No one needs a reason."},{"icon":"heart","title":"What is shared stays here","body":"Take the lessons home. Leave the stories and the names in the room."},{"icon":"users","title":"Speak for yourself","body":"Use I. Speak from your own life, not about anyone else''s."},{"icon":"message","title":"No fixing","body":"Listen without advising, correcting or rescuing. Ask an honest question, or simply say thank you."},{"icon":"calendar","title":"Start and end on time","body":"A clear start and a clear end are a kindness. People can plan around you."},{"icon":"award","title":"Ask before touch","body":"No touch without a clear yes, every time. Nothing sexual happens in a circle."}],"register":"auto"}},{"type":"NewWorldFirstVisit","props":{"id":"fh-training-care-l","index":"06","eyebrow":"When something comes up","title":"Safe enough *to be honest.*","lede":"Our training follows the six principles of a trauma-informed approach: safety, trust and transparency, peer support, collaboration, choice and voice, and culture and context.","note":"A Frequency circle is practice and community, not therapy or crisis care. In the US, call or text 988 for the Suicide and Crisis Lifeline. If anyone is in immediate danger, call emergency services.","rows":[{"title":"Strong feelings","body":"Slow down. Let the person finish, thank them, and offer a breath for the whole circle. Tears aren''t an emergency."},{"title":"A disclosure","body":"Thank them, don''t press for details in the circle, and speak privately afterwards. Share the local crisis line."},{"title":"One voice filling the room","body":"Use the talking piece. Set a time per share before the round starts. Invite someone who hasn’t spoken yet."},{"title":"After a hard night","body":"Debrief with your co-host or mentor within a day. Hosting is a team practice."}],"register":"auto"}},{"type":"NewWorldCloser","props":{"id":"fh-closer-creator-lab-17","aside":"Generous structure. Real care. On time.","title":"Start with *one course.*","primaryLabel":"The Business of Community","primaryHref":"/spaces/hq/business-of-community","secondaryLabel":"Start Host Foundations","secondaryHref":"/journeys/host-foundations","note":"","register":"auto"}}]},"business-of-community":{"root":{"props":{}},"content":[{"type":"PhotoHero","props":{"id":"boc-hero-0","variant":"image","display":"beside","height":"medium","scrim":"light","image":"/sites/new-world/photos/beach-joy.webp","alt":"Friends laughing together on a beach at golden hour","eyebrow":"Live workshop · Free","title":"People showed up once. Here’s how they come back.","accentWord":"Here’s how they come back.","subtitle":"The Business of Community is Frequency’s free four-week live workshop for anyone who gathers people. Four simple meetings you can run, all on the PULSE rhythm. It assumes you’re starting from scratch.","actionPrimaryLabel":"Save your seat","actionPrimaryHref":"/events/business-of-community-pilot-session-1","actionSecondaryLabel":"Join the January Run","actionSecondaryHref":"/circles/business-of-community-january-2027","note":"Thursdays, January 7 to 28 · 10 to 11:30 AM Pacific · on Zoom"}},{"type":"Zigzag","props":{"id":"boc-idea-1","image":"/sites/new-world/photos/circle-sunrise.webp","alt":"A small group sitting in a circle outdoors at sunrise","mediaSide":"right","background":"canvas","eyebrow":"The one idea","title":"Frequency. The how-often kind.","accentWord":"The how-often kind.","body":"lead","lead":"Most people who gather others count heads. How many came. How full it looked.<br><br>A community lives on a different number: how many came back. A small room where people return is healthier than a big room you never see again. That number runs through all four weeks.","items":[],"quoteBy":"","ctaLabel":"","ctaHref":""}},{"type":"CardGrid","props":{"id":"boc-weeks-2","role":"step","columns":2,"eyebrow":"The four weeks","title":"Four meetings you can run.","accentWord":"you can run.","cards":[{"title":"Jan 7 · The weekly sit-down","body":"A weekly 30-minute meeting with yourself that keeps you from carrying everything at once."},{"title":"Jan 14 · The opening","body":"An opening you can run every time: your purpose in one line, three agreements read aloud, and a check-in round."},{"title":"Jan 21 · The full gathering","body":"A one-page run sheet for a 90-minute gathering, and a ten-minute habit the next day to see who came back."},{"title":"Jan 28 · The money hour","body":"Your break-even number, one price you can say without flinching, and a monthly hour to keep both honest."}],"browseLabel":"","browseHref":""}},{"type":"Zigzag","props":{"id":"boc-week-3","image":"/sites/new-world/photos/workshop-table.webp","alt":"Adults and kids making crafts around a long table in a workshop room","mediaSide":"left","background":"accent-wash","eyebrow":"How each week works","title":"Read it. Practice it. Run it.","accentWord":"Run it.","body":"list","lead":"","items":[{"text":"Before Thursday, about 15 minutes: a short overview and one lesson."},{"text":"Thursday, 90 minutes live on Zoom, on PULSE: a story, check-ins in small groups, the meeting and a practice run, a moment to steady, and one commitment said out loud."},{"text":"After: run the meeting once with your own people, fill in your one page, and post a three-line report back to your Run."}],"quoteBy":"","ctaLabel":"Save your seat","ctaHref":"/events/business-of-community-pilot-session-1"}},{"type":"CardGrid","props":{"id":"boc-guides-4","role":"media","columns":2,"eyebrow":"Your guides","title":"Hosted by Frequency. Led by Daniel and Feargal.","accentWord":"Led by Daniel and Feargal.","cards":[{"image":"/brand/frequency/photos/guide-daniel-tyack.jpg","alt":"Daniel Tyack","title":"Daniel Tyack","body":"Founder of Frequency. Daniel has spent years building and leading rooms, from music to men’s work to ceremony, and created PULSE, the rhythm the workshop runs on."},{"image":"/brand/frequency/photos/guide-feargal-walsh.jpg","alt":"Feargal Walsh","title":"Feargal Walsh","body":"Leads technology and member experience at Frequency. Feargal turns the systems organizers need into tools that are simple to run week after week."}],"browseLabel":"","browseHref":""}},{"type":"CardGrid","props":{"id":"boc-ways-5","role":"feature","columns":2,"eyebrow":"Two ways in","title":"Four weeks together, then every week.","accentWord":"then every week.","cards":[{"icon":"◎","title":"The live workshop","body":"Free for anyone, Space or not. Four Thursdays on Zoom, 10 to 11:30 AM Pacific, several times a year. The launch Run meets January 7 to 28.","button":{"label":"Save your seat","href":"/events/business-of-community-pilot-session-1"}},{"icon":"↗","title":"Business Hours","body":"For Spaces on the Business plan. Wednesday mornings at 10 AM Pacific on Zoom, run on PULSE in a members-only Circle. Bring one number and one stuck thing.","button":{"label":"See the Circle","href":"/circles/business-hours"}}],"browseLabel":"See the Business plan","browseHref":"/pricing"}},{"type":"Zigzag","props":{"id":"boc-finish-6","image":"/sites/new-world/photos/fire-circle.webp","alt":"People sitting around a fire at dusk","mediaSide":"right","background":"canvas","eyebrow":"Two ways to finish","title":"Attended or Certified.","accentWord":"Certified.","body":"list","lead":"","items":[{"text":"Attended: come to all four live sessions."},{"text":"Certified: send in your Community Book, your four pages filled in from real gatherings. Review is free for Community Books submitted by February 28, 2027, then comes with the Business plan."},{"text":"Certified is a certificate of completion and competency from Frequency. It is not an accredited certification."}],"quoteBy":"","ctaLabel":"","ctaHref":""}},{"type":"EditorialSection","props":{"id":"boc-faq-7","eyebrow":"Questions","title":"Good to know.","accentWord":"know.","kicker":"Anything else, ask. A person on the Frequency team answers.","body":"faq","surface":"open","lead":"","stats":[],"faqs":[{"q":"What does it cost?","a":"Nothing. The workshop is free for anyone. Certified review is free for Community Books submitted by February 28, 2027, then comes with the Business plan."},{"q":"When is the next workshop?","a":"The launch Run meets Thursdays, 10 to 11:30 AM Pacific, on Zoom: January 7, 14, 21 and 28, 2027, the month Frequency launches. Anyone can join. Save your seat on the Week 1 event and the Zoom link comes to you. New Runs start through the year."},{"q":"How much time does it take?","a":"About three hours a week. Before Thursday, 15 minutes: a short overview and one lesson. Thursday, 90 minutes live. After, your homework: run that week’s meeting once with your own people and post a three-line report back."},{"q":"I haven’t started anything yet. Is it for me?","a":"Yes. It assumes you’re starting from scratch. If you run something already, you’ll fix the parts that wear you out."},{"q":"What is PULSE?","a":"The five-beat rhythm every Frequency gathering follows: Presence, Unite, Lead, Settle, Exhale. Every meeting in this workshop runs on it, and so does each session."},{"q":"Do I need a Space?","a":"No. Everything works on paper and a phone. If you have a Space, each week ends with an optional step to set it up there."},{"q":"What is Business Hours?","a":"A weekly hour on Zoom for Spaces on the Business plan, Wednesday mornings at 10 AM Pacific, run on PULSE in a members-only Circle. Bring one number and one stuck thing."},{"q":"Is it accredited?","a":"No. Certified is a certificate of completion and competency from Frequency, not an accredited certification."}]}},{"type":"AccentBeat","props":{"id":"boc-closer-8","mode":"cta","background":"accent-wash","image":"","alt":"","eyebrow":"Free · Four weeks · Live on Zoom","title":"Keep the room. Keep yourself.","accentWord":"Keep yourself.","body":"The launch Run starts Thursday, January 7.","quoteBy":"","ctaLabel":"Save your seat","ctaHref":"/events/business-of-community-pilot-session-1","ctaSecondaryLabel":"Ask a question","ctaSecondaryHref":"/spaces/hq/help"}}]},"help":{"root":{"props":{}},"content":[{"type":"NewWorldPageHead","props":{"id":"fh-help-head-u","index":"","eyebrow":"Help desk","title":"Ask. *A person answers.*","lede":"Open a help ticket, browse the help center, or ask the community. Every ticket is read by a real person on the Frequency team.","register":"auto"}},{"type":"NewWorldWayRows","props":{"id":"fh-help-rows-v","costLabel":"Cost","whenLabel":"Best for","buttonLabel":"Open a help ticket","buttonHref":"/support","secondaryLabel":"Common questions","secondaryHref":"#faq","rows":[{"icon":"message","tags":"Help desk","name":"Open a help ticket","body":"Tell us what happened. Follow every reply from your tickets.","price":"Free","when":"Your account, billing, bugs","image":"/sites/new-world/photos/cafe-table.webp","alt":"Three people talking at a small table in a cafe","buttonLabel":"Open a ticket","href":"/support"},{"icon":"check","tags":"Help center","name":"Browse the help center","body":"Plain answers on Circles, events, Spaces, The Quest and membership.","price":"Free","when":"How-to questions","image":"/sites/new-world/photos/garden-picnic.webp","alt":"People gathered on rugs and cushions in a leafy backyard garden","buttonLabel":"Open the help center","href":"/help"},{"icon":"users","tags":"Forum","name":"Ask the community","body":"Post a question or an idea. Members, hosts and the team answer.","price":"Free","when":"Ideas and how others do it","image":"/brand/frequency/photos/gathering-12.jpg","alt":"A tight group hugging and laughing on a seaside deck","buttonLabel":"Go to the forum","href":"/spaces/hq/community"},{"icon":"heart","tags":"Safety","name":"Report a safety concern","body":"Reporting, blocking and how moderation works. In an emergency, call emergency services first.","price":"Free","when":"Anything that feels unsafe","image":"/sites/new-world/photos/fire-circle.webp","alt":"People sitting quietly around a fire pit in the evening","buttonLabel":"Safety and reporting","href":"/help/safety"}],"register":"auto"}},{"type":"NewWorldPosts","props":{"id":"fh-help-center-w","index":"01","eyebrow":"Help center","title":"Find it *fast.*","lede":"Seven topics, written in plain words.","buttonLabel":"Open the help center","buttonHref":"/help","rows":[{"kind":"Start here","title":"Getting started: what Frequency is and how to find your people","meta":"","href":"/help/getting-started"},{"kind":"Groups","title":"Circles and events: how gatherings work","meta":"","href":"/help/groups"},{"kind":"Hosting","title":"Leading a Circle: start one, run the first night, keep it going","meta":"","href":"/help/leading"},{"kind":"Spaces","title":"Running a Space: the tools a Space gives you","meta":"","href":"/help/spaces"},{"kind":"The Quest","title":"Zaps, Gems, ranks and rewards","meta":"","href":"/help/the-quest"},{"kind":"Membership","title":"What''s free and what Crew adds","meta":"","href":"/help/membership"},{"kind":"Safety","title":"Reporting, blocking and how moderation works","meta":"","href":"/help/safety"}],"register":"auto"}},{"type":"NewWorldFaq","props":{"id":"fh-help-faq-x","index":"02","eyebrow":"Questions","title":"Good to *know.*","lede":"Still stuck? Open a ticket or email us.","phone":"","email":"hello@frequencylocal.com","hours":"","areasLabel":"","areas":[],"rows":[{"question":"How do I open a help ticket?","answer":"Go to Help and support, describe what happened, and send it. You can follow every reply from your tickets on the same page."},{"question":"Something feels unsafe. What do I do?","answer":"Use Report on the post, profile or event, or open a ticket marked safety. If anyone is in immediate danger, call emergency services first."},{"question":"I have a billing question.","answer":"Open a ticket and choose billing. Include the email on your account so we can find it quickly."},{"question":"How do I start a Space for my business or group?","answer":"Read Running a Space in the help center, then create one from the Spaces page. The help desk can walk you through it."},{"question":"Can I suggest a feature?","answer":"Yes, please. Post it in the community forum so others can add to it, or open a ticket if it is about your own account."}],"register":"auto"}},{"type":"NewWorldCloser","props":{"id":"fh-closer-help-y","aside":"Generous structure. Real care. On time.","title":"Still stuck? *Ask us.*","primaryLabel":"Open a help ticket","primaryHref":"/support","secondaryLabel":"Ask the community","secondaryHref":"/spaces/hq/community","note":"","register":"auto"}}]},"about":{"root":{"props":{}},"content":[{"type":"NewWorldAboutHero","props":{"id":"fh-about-hero-z","eyebrow":"Our story · Frequency","title":"Build circles, *not walls.*","lead":"Frequency is a community collective that spreads town by town through local hosts. This Space is where the team shares the programs, the training, the answers and the conversation in the open.","chips":[{"icon":"check","text":"Free to start"},{"icon":"users","text":"Run with its members"},{"icon":"heart","text":"Care designed in"}],"primaryLabel":"Explore programs","primaryHref":"/spaces/hq/programs","secondaryLabel":"Ask the community","secondaryHref":"/spaces/hq/community","image":"/sites/new-world/photos/circle-sunrise.webp","alt":"A wide circle of people seated on a plaza at sunrise","name":"Daniel Tyack","role":"Founder","register":"auto"}},{"type":"NewWorldLongStory","props":{"id":"fh-about-roots-10","index":"01","eyebrow":"Where this comes from","title":"Old practices, *plain words.*","paragraphs":["Sitting in a circle and taking turns to speak is one of the oldest ways people have gathered. We did not invent it. We gave it a rhythm, PULSE, that a new host can learn in a week and a returning guest can trust.","Our host training draws on a few sources worth reading in full. The Way of Council, as taught by Jack Zimmerman and Virginia Coyle, gives us the talking piece and its intentions. Parker Palmer and the Center for Courage and Renewal give us touchstones for trustworthy space, like no fixing and honest, open questions. Priya Parker gives us generous authority: a host who protects, connects and equalizes the room. SAMHSA gives us the six principles of a trauma-informed approach.","Everything is written in plain words, because a host should be able to read an agreement aloud without explaining it."],"register":"auto"}},{"type":"NewWorldQuote","props":{"id":"fh-about-quote-11","label":"In Daniel’s words","quote":"The structure exists to serve the circle. The circle *governs the structure.*","by":"Daniel Tyack · Founder","register":"auto"}},{"type":"NewWorldTeam","props":{"id":"fh-about-team-12","index":"02","eyebrow":"The team","title":"Who *runs this.*","lede":"","note":"Trained hosts join this list as they become mentors.","rows":[{"name":"Daniel Tyack","role":"Founder · The Janitor","image":"/brand/frequency/photos/daniel-tyack.jpg","alt":"Daniel Tyack smiling"}],"register":"auto"}},{"type":"NewWorldCloser","props":{"id":"fh-closer-about-13","aside":"Generous structure. Real care. On time.","title":"Pick a door. *Come in.*","primaryLabel":"Ask the community","primaryHref":"/spaces/hq/community","secondaryLabel":"Get help","secondaryHref":"/support","note":"","register":"auto"}}]}},"siteHero":{"eyebrow":"Frequency · Programs, training and help","heading":"Gather like it *matters.*","tagline":"Our programs, free host training, a help desk with real people and a community forum, in one place.","action":{"label":"Explore programs","href":"/spaces/hq/programs"},"secondary":{"label":"Get help","href":"/spaces/hq/help"}},"headerCta":{"kind":"custom","url":"/support","label":"Get help"},"coverFocus":"50% 45%","coverScrim":"none","coverSize":"hero","logoBackdrop":"none","profileLayout":{"rows":[{"id":"r0","columns":1,"cells":[["editorial"]]},{"id":"r1","columns":1,"cells":[["links"]],"title":"Start here","headerOn":true},{"id":"r2","columns":1,"cells":[["cardGrid"]]},{"id":"r3","columns":1,"cells":[["practices"]]},{"id":"r4","columns":1,"cells":[["zigzag"]]},{"id":"r5","columns":1,"cells":[["offerings"]]},{"id":"r6","columns":1,"cells":[["quote"]]},{"id":"r7","columns":1,"cells":[["faq"]]},{"id":"r8","columns":1,"cells":[["accentBeat"]]},{"id":"r9","columns":2,"cells":[["contact"],["team"]],"title":"Contact and team","headerOn":true}],"content":{"about":{"eyebrow":"About","title":"About this Space","body":"This is the Frequency team''s own Space: the home base for everyone building Frequency. Find our programs, take free host training on the PULSE rhythm, learn to run your community in Creator Lab, get help from a real person, and ask the community in the forum."},"editorial":{"eyebrow":"The Frequency Space","title":"Gather like it matters.","body":"This is the Frequency team''s own Space: the home base for members, hosts and Spaces.<br><br>Find our programs, take free host training on the PULSE rhythm, open a help ticket when something breaks, and ask the community anything in the forum. Everything here is free to walk into."},"links":{"items":[{"label":"Open a help ticket","url":"/support"},{"label":"Ask the community","url":"/spaces/hq/community"},{"label":"Start host training","url":"/journeys/host-foundations"},{"label":"Help center","url":"/help"},{"label":"Creator Lab","url":"/spaces/hq/creator-lab"},{"label":"Find a Circle","url":"/circles"}]},"cardGrid":{"eyebrow":"Inside","title":"Five doors.","subtitle":"Everything the Frequency team runs for members, hosts and Spaces.","columns":"3","shadow":false,"cards":[{"icon":"1","title":"Programs","text":"The Quest, Circles, events and host training: the structured ways to take part."},{"icon":"2","title":"Host training","text":"Free courses on the PULSE rhythm, care and consent, and the three circle formats."},{"icon":"3","title":"Help desk","text":"Open a ticket, browse the help center, or report something that feels off. A real person answers."},{"icon":"4","title":"Creator Lab","text":"Core training for community creators, starting with The Business of Community 101. Free for anyone."},{"icon":"5","title":"Community forum","text":"Ask a question, share what worked, suggest a feature. Hosts and the team read it."}]},"practices":{"eyebrow":"Learn here","title":"Courses to start"},"zigzag":{"eyebrow":"The PULSE rhythm","title":"Five beats. Every circle.","body":"<b>Presence.</b> Arrive. A few slow breaths, feet on the floor, phones away. The host sets the tone by going first.<br><br><b>Unite.</b> A check-in round. Each person says how they''re arriving, and everyone else listens without replying.<br><br><b>Lead.</b> Tonight''s practice: a teaching, a movement, a conversation or a skill. The part that changes from week to week.<br><br><b>Settle.</b> Quiet integration. Rest, journal or sit with what came up before anyone has to talk about it.<br><br><b>Exhale.</b> Close together. One word or one line each, a thank you, and a clear end.","image":"/brand/frequency/photos/day-meditation-circle.jpg","alt":"A large circle of people seated on the grass by the ocean, eyes closed","mediaSide":"right"},"offerings":{"eyebrow":"Frequency Programs","title":"Show up. Come back."},"quote":{"text":"The structure exists to serve the circle. The circle governs the structure.","by":"Daniel Tyack · Founder"},"faq":{"eyebrow":"Questions","title":"Good to know"},"accentBeat":{"eyebrow":"Help desk","title":"Need a hand?","body":"Open a help ticket and a real person on the Frequency team answers. You can follow every reply from your tickets.","buttonOn":true,"buttonLabel":"Open a help ticket","buttonUrl":"/support"},"contact":{"eyebrow":"Contact","title":"Reach the team"},"team":{"eyebrow":"The team","title":"Who runs this"}}},"websiteEditor":{"v":1,"revision":1,"draft":{"theme":"NewWorld","brand":{"logo":"/brand/frequency/logo/frequency-icon-round.png","accent":"#1AA7C0"},"chrome":{"name":"Frequency","tagline":"Gather like it matters.","cta":{"label":"Get help","href":"/support"}},"pages":[{"slug":"home","label":"Home","doc":{"root":{"props":{}},"content":[{"type":"NewWorldHero","props":{"id":"fh-home-hero-18","eyebrow":"Frequency · Programs, training and help","title":"Gather like it *matters.*","lead":"The home base for everyone building Frequency. Find our programs, learn to host on the PULSE rhythm, get help from a real person, and ask the community anything. Start wherever you are.","primaryLabel":"Explore programs","primaryHref":"/spaces/hq/programs","secondaryLabel":"Get help","secondaryHref":"/spaces/hq/help","proof":"Run by the Frequency team, for members, hosts and Spaces.","aside":"We build circles, not walls.","image":"/brand/frequency/photos/day-meditation-circle.jpg","alt":"A large circle of people seated on the grass by the ocean, eyes closed","badge":"Open to everyone","useEvents":true,"rows":[{"weekday":"Help","mon":"Desk","day":"1","title":"Open a help ticket","body":"A real person reads every ticket.","time":"Any time","where":"Online","spots":"Open","kind":"session","href":"/support"},{"weekday":"Workshop","mon":"Free","day":"2","title":"The Business of Community","body":"A free four-week live workshop on the PULSE rhythm. Starts January 7.","time":"4 weeks · live on Zoom","where":"Online","spots":"Open","kind":"session","href":"/events/business-of-community-pilot-session-1"},{"weekday":"Course","mon":"Free","day":"3","title":"Host Foundations","body":"Four short weeks on the craft every Frequency host shares: why we gather, the PULSE rhythm, setting the room, and running your first circle.","time":"Self-paced · 4 parts","where":"Online","spots":"Open","kind":"session","href":"/journeys/host-foundations"}],"register":"auto"}},{"type":"NewWorldStats","props":{"id":"fh-home-stats-19","items":[{"icon":"heart","value":"4","label":"Pillars","note":"Mind, Body, Spirit, Expression"},{"icon":"users","value":"5","label":"beats in every circle","note":"Presence, Unite, Lead, Settle, Exhale"},{"icon":"calendar","value":"4","label":"host courses","note":"Three free online, one in person"},{"icon":"check","value":"1","label":"help desk","note":"A real person answers"}],"register":"auto"}},{"type":"NewWorldPromises","props":{"id":"fh-home-doors-1a","index":"01","eyebrow":"Inside","title":"Five *doors.*","lede":"Everything the Frequency team runs for members, hosts and Spaces.","rows":[{"icon":"award","title":"Programs","body":"The Quest, Circles, events and host training: the structured ways to take part."},{"icon":"heart","title":"Host training","body":"Free courses on the PULSE rhythm, care and consent, and the three circle formats."},{"icon":"check","title":"Help desk","body":"Open a ticket, browse the help center, or report something that feels off."},{"icon":"sparkle","title":"Creator Lab","body":"Business and leadership for the people who gather others. Starts with The Business of Community 101."},{"icon":"users","title":"Community forum","body":"Ask a question, share what worked, suggest a feature. Hosts and the team read it."}],"register":"auto"}},{"type":"NewWorldStory","props":{"id":"fh-home-story-1b","index":"02","eyebrow":"A community collective","title":"Built by *its members.*","paragraphs":["Frequency is a community collective, not just an app. The software helps people find each other and helps local hosts and businesses run their rooms. The point is the room.","We grow town by town, one circle at a time. Every one of those circles needs someone who arrives early, sets the chairs, starts on time and makes the new person feel expected.","This Space is where that work is shared in the open: the programs, the training, the answers and the conversation."],"buttonLabel":"Our story","buttonHref":"/spaces/hq/about","secondaryLabel":"Ask the community","secondaryHref":"/spaces/hq/community","image":"/brand/frequency/photos/gathering-03.jpg","alt":"People gathered on rugs and cushions in a leafy garden","quote":"The structure exists to serve the circle.","quoteBy":"Daniel Tyack · Founder","register":"auto"}},{"type":"SpacePractices","props":{"id":"fh-home-journeys-1c","eyebrow":"Learn here","heading":"Courses to start","practicesHeading":"Practices","journeysHeading":"Courses","only":""}},{"type":"NewWorldProcess","props":{"id":"fh-home-path-1d","index":"03","eyebrow":"Host training","title":"From guest to *host.*","lede":"","rows":[{"icon":"calendar","title":"Learn","body":"Take Host Foundations, free and self-paced. Four short weeks on the PULSE rhythm."},{"icon":"heart","title":"Learn to care","body":"Take Safe and Well Held: agreements, consent and what to do when something comes up."},{"icon":"users","title":"Co-host","body":"Run two circles beside a trained host. Lead one beat, then two, then the whole night."},{"icon":"award","title":"Host","body":"Open your own circle with a mentor on call, then join the monthly Host Circle."}],"register":"auto"}},{"type":"NewWorldGallery","props":{"id":"fh-home-gallery-1e","index":"04","eyebrow":"Real circles","title":"Rooms people *come back to.*","lede":"Photos from Frequency gatherings.","images":[{"image":"/brand/frequency/photos/gathering-04.jpg","alt":"A circle seated on a lawn with arms stretched wide"},{"image":"/brand/frequency/photos/gathering-12.jpg","alt":"A tight group hugging and laughing on a seaside deck"},{"image":"/brand/frequency/photos/day-parachute-play.jpg","alt":"People holding a rainbow parachute on a clifftop lawn"},{"image":"/brand/frequency/photos/gathering-14.jpg","alt":"A circle on mats around a gong at the water"},{"image":"/brand/frequency/photos/gathering-13.jpg","alt":"A group moving together on the beach at golden hour"}],"register":"auto"}},{"type":"NewWorldFaq","props":{"id":"fh-home-faq-1f","index":"05","eyebrow":"Questions","title":"Good to *know.*","lede":"Anything else, ask. A real person answers.","phone":"","email":"hello@frequencylocal.com","hours":"","areasLabel":"","areas":[],"rows":[{"question":"What is this Space?","answer":"The Frequency team''s own Space: our programs, host training, Creator Lab, the help desk and a community forum, in one place. Follow it to hear what''s new."},{"question":"How do I get help with my account?","answer":"Open a help ticket from the help desk. A real person reads every one, and you can follow the reply from your tickets."},{"question":"Do I need experience to host?","answer":"No. Most Frequency hosts started as guests. Host Foundations and the apprenticeship take you from your first seat in the circle to running your own."},{"question":"Can my organization train its own hosts here?","answer":"Yes. The courses and the PULSE rhythm are built so partner organizations and volunteers can use them for their own in-person and online groups."},{"question":"Where do I ask other members a question?","answer":"In the community forum. Post a question, share what worked, or say hello. Hosts and the team read it too."}],"register":"auto"}},{"type":"NewWorldCloser","props":{"id":"fh-closer-home-1g","aside":"Generous structure. Real care. On time.","title":"Pick a door. *Come in.*","primaryLabel":"Ask the community","primaryHref":"/spaces/hq/community","secondaryLabel":"Get help","secondaryHref":"/support","note":"","register":"auto"}}]},"seo":{"title":"Frequency","description":"Frequency: programs, free host training, Creator Lab, a help desk and a community forum."},"comments":[]},{"slug":"programs","label":"Programs","doc":{"root":{"props":{}},"content":[{"type":"NewWorldPageHead","props":{"id":"fh-programs-head-1h","index":"","eyebrow":"Frequency Programs","title":"Show up. *Come back.*","lede":"Frequency Programs are the structured ways to take part: The Quest, Circles, local events and host training. Start with one.","register":"auto"}},{"type":"NewWorldWayRows","props":{"id":"fh-programs-rows-1i","costLabel":"For","whenLabel":"Rhythm","buttonLabel":"Start","buttonHref":"/circles","secondaryLabel":"Questions","secondaryHref":"/spaces/hq/help","rows":[{"icon":"award","tags":"Program","name":"The Quest","body":"Daily practices and Journeys you take with your Circle, across the four Pillars. Show up, earn Zaps and Gems, and climb the season.","price":"Every member","when":"Daily","image":"/brand/frequency/photos/gathering-13.jpg","alt":"A group moving together on the beach at golden hour","buttonLabel":"How The Quest works","href":"/help/the-quest"},{"icon":"users","tags":"Program","name":"Circles","body":"Small groups of 12 to 18 people who meet at the same time in the same place, on the PULSE rhythm.","price":"Every member","when":"Weekly or every other week","image":"/brand/frequency/photos/gathering-04.jpg","alt":"A circle seated on a lawn with arms stretched wide","buttonLabel":"Find a Circle","href":"/circles"},{"icon":"calendar","tags":"Program","name":"What''s happening","body":"Local events from Circles and Spaces near you. RSVP, add it to your calendar, bring someone.","price":"Everyone","when":"Any week","image":"/brand/frequency/photos/day-parachute-play.jpg","alt":"People holding a rainbow parachute on a clifftop lawn","buttonLabel":"See what''s happening","href":"/events"},{"icon":"sparkle","tags":"Program","name":"Creator Lab","body":"Core training for the people who gather others. The Business of Community is a free four-week live workshop on Zoom, run several times a year; the Business plan adds Business Hours on Zoom.","price":"Anyone","when":"One week at a time","image":"/brand/frequency/photos/gathering-03.jpg","alt":"People gathered on rugs and cushions in a leafy garden","buttonLabel":"Open Creator Lab","href":"/spaces/hq/creator-lab"},{"icon":"heart","tags":"Program","name":"Host training","body":"Free courses on the PULSE rhythm, care and consent, and the three circle formats, then a co-host apprenticeship.","price":"Hosts and future hosts","when":"Self-paced","image":"/brand/frequency/photos/day-meditation-circle.jpg","alt":"A large circle of people seated on the grass by the ocean, eyes closed","buttonLabel":"Start host training","href":"/spaces/hq/creator-lab"}],"register":"auto"}},{"type":"NewWorldPromises","props":{"id":"fh-programs-pillars-1j","index":"01","eyebrow":"The Quest","title":"Four *Pillars.*","lede":"Every practice and Journey sits under one Pillar, so you build the same strengths all year in different forms.","rows":[{"icon":"sparkle","title":"Mind","body":"Calm down fast, focus, and think clearly. Practices like breathing, journaling and less scrolling."},{"icon":"heart","title":"Body","body":"Move, rest, eat and sleep like you mean it. Walks, stretching, cold water, early nights."},{"icon":"users","title":"Spirit","body":"Meaning, gratitude and time with people. Stillness, service and showing up for each other."},{"icon":"award","title":"Expression","body":"Make something and share it. The weekly Expression Challenge, alone or with your Circle."}],"register":"auto"}},{"type":"NewWorldProcess","props":{"id":"fh-programs-quest-1k","index":"02","eyebrow":"How The Quest works","title":"Small things, *every day.*","lede":"","rows":[{"icon":"calendar","title":"Pick a Journey","body":"Choose one under a Pillar. Each has a few minutes of practice a day."},{"icon":"check","title":"Practice daily","body":"Log it when you do it. Streaks build, and misses are part of it."},{"icon":"users","title":"Bring your Circle","body":"Take a Journey with your Circle and show up for each other in person."},{"icon":"award","title":"Earn as you go","body":"Zaps and Gems for showing up, a Pillar Trophy when you finish a Journey."}],"register":"auto"}},{"type":"NewWorldCloser","props":{"id":"fh-closer-programs-1l","aside":"Generous structure. Real care. On time.","title":"Start with *one.*","primaryLabel":"Find a Circle","primaryHref":"/circles","secondaryLabel":"See what''s happening","secondaryHref":"/events","note":"","register":"auto"}}]},"seo":{"title":"Programs · Frequency","description":"Frequency Programs: The Quest, Circles, local events and host training."},"comments":[]},{"slug":"creator-lab","label":"Creator Lab","doc":{"root":{"props":{}},"content":[{"type":"NewWorldPageHead","props":{"id":"fh-lib-head-2c","index":"","eyebrow":"Creator Lab","title":"Courses for the people who *gather others.*","lede":"Free courses in two tracks: hosting the room, and running the community behind it. Start anywhere. Every course ends with you doing it for real.","register":"auto"}},{"type":"NewWorldPromises","props":{"id":"fh-lib-tracks-2d","index":"01","eyebrow":"The library","title":"Two *tracks.*","lede":"Each course is free. The Business plan adds a weekly room on Zoom.","rows":[{"icon":"heart","title":"Hosting","body":"The PULSE rhythm, care and consent, the three circle formats, and an apprenticeship beside a trained host."},{"icon":"sparkle","title":"Business and leadership","body":"The Business of Community: four simple meetings on PULSE that bring people back, and keep you going."}],"register":"auto"}},{"type":"NewWorldWayRows","props":{"id":"fh-lib-rows-2e","costLabel":"Cost","whenLabel":"Length","buttonLabel":"Start a course","buttonHref":"/spaces/hq/business-of-community","secondaryLabel":"Questions","secondaryHref":"/spaces/hq/help","rows":[{"icon":"calendar","tags":"Business · 4 weeks","name":"The Business of Community","body":"Frequency’s free live workshop. Four 90-minute sessions on Zoom, all on PULSE: the weekly sit-down, the opening, the full gathering and the money hour. Short lessons to read before each one.","price":"Free","when":"4 weeks","image":"/brand/frequency/photos/gathering-04.jpg","alt":"A circle seated on a lawn with arms stretched wide","buttonLabel":"See the workshop","href":"/spaces/hq/business-of-community"},{"icon":"users","tags":"Business · January Run","name":"The January Run","body":"Everyone in the launch Run, together. A thread to share what you tried between sessions, and someone noticing when you don’t show. Thursdays Jan 7, 14, 21 and 28.","price":"Free","when":"Starts January 7","image":"/brand/frequency/photos/gathering-12.jpg","alt":"A tight group hugging and laughing on a seaside deck","buttonLabel":"Join the Run","href":"/circles/business-of-community-january-2027"},{"icon":"message","tags":"Business · Zoom","name":"Business Hours","body":"Same hour every week, run on PULSE. Bring one number and one stuck thing. Last week’s commitments read back, one hot seat, and a new commitment each.","price":"Business plan","when":"Wednesdays · 10 AM Pacific","image":"/sites/new-world/photos/cafe-table.webp","alt":"Three people talking at a small table in a cafe","buttonLabel":"See the Circle","href":"/circles/business-hours"},{"icon":"calendar","tags":"Hosting · Online","name":"Host Foundations","body":"Four short weeks on the craft every Frequency host shares: why we gather, the PULSE rhythm, setting the room, and running your first circle.","price":"Free","when":"4 parts","image":"/brand/frequency/photos/day-meditation-circle.jpg","alt":"","buttonLabel":"Start the course","href":"/journeys/host-foundations"},{"icon":"heart","tags":"Hosting · Online","name":"Safe and Well Held","body":"Agreements, consent and care: how to keep a room safe enough to be honest, and what to do when something comes up.","price":"Free","when":"4 parts","image":"/brand/frequency/photos/gathering-12.jpg","alt":"","buttonLabel":"Start the course","href":"/journeys/safe-and-well-held"},{"icon":"users","tags":"Hosting · Online","name":"The Three Circle Formats","body":"Open, Community and Focus Circles: what each one is for, what the host does, and how to choose.","price":"Free","when":"4 parts","image":"/brand/frequency/photos/gathering-03.jpg","alt":"","buttonLabel":"Start the course","href":"/journeys/circle-formats"},{"icon":"award","tags":"Hosting · In person","name":"Co-host Apprenticeship","body":"Learn by doing: shadow a trained host, co-lead two circles, then host your own with a mentor on call.","price":"Ask us","when":"Three circles","image":"/brand/frequency/photos/gathering-04.jpg","alt":"","buttonLabel":"Ask about a mentor","href":"/journeys/co-host-apprenticeship"}],"register":"auto"}},{"type":"NewWorldProcess","props":{"id":"fh-pulse-beats-1p","index":"02","eyebrow":"The PULSE rhythm · for everyone","title":"What each beat *is.*","lede":"","rows":[{"icon":"heart","title":"P · Presence","body":"Arrive. A few slow breaths, feet on the floor, phones away. The host sets the tone by going first."},{"icon":"users","title":"U · Unite","body":"A check-in round. Each person says how they''re arriving, and everyone else listens without replying."},{"icon":"award","title":"L · Lead","body":"Tonight''s practice: a teaching, a movement, a conversation or a skill. The part that changes from week to week."},{"icon":"check","title":"S · Settle","body":"Quiet integration. Rest, journal or sit with what came up before anyone has to talk about it."},{"icon":"message","title":"E · Exhale","body":"Close together. One word or one line each, a thank you, and a clear end."}],"register":"auto"}},{"type":"NewWorldFirstVisit","props":{"id":"fh-pulse-host-1q","index":"03","eyebrow":"The PULSE rhythm · for the host","title":"What you *do.*","lede":"A 90-minute night, beat by beat.","note":"Shorter night? Trim Lead first. Never skip Exhale.","rows":[{"title":"Presence · 10 min","body":"Start on time. Welcome people by name. Name the purpose of tonight in one sentence."},{"title":"Unite · 20 min","body":"Read the agreements. Ask one question everyone can answer. Keep it lean so everyone gets a turn."},{"title":"Lead · 35 min","body":"Give clear steps, an invitation and an opt-out. Watch the room more than your notes."},{"title":"Settle · 15 min","body":"Lower the pace. Offer a simple prompt. Let silence do some of the work."},{"title":"Exhale · 10 min","body":"End on time. Say what happens next and how people can reach you."}],"register":"auto"}},{"type":"NewWorldPromises","props":{"id":"fh-training-formats-1r","index":"04","eyebrow":"One rhythm","title":"Three *formats.*","lede":"Every circle runs on PULSE. The format decides how much you teach and how big the room gets.","rows":[{"icon":"users","title":"Open Circle · 12 to 18 people","body":"The host keeps the room, with no teaching agenda. People come to be heard and to hear each other. You open and close, keep the agreements and the time, and pass the turn. You speak least."},{"icon":"heart","title":"Community Circle · 12 to 18 people","body":"A hosted circle around one shared theme: moon circles, men''s and women''s circles, grief, new parents, sharing circles. You choose the theme and the question for the round, and keep the circle on it."},{"icon":"award","title":"Focus Circle · Up to 50 people","body":"The host teaches a modality: breathwork, sound, movement, a skill. The PULSE rhythm wraps the teaching so the room still feels like a circle. You teach in the Lead beat, and the four beats around it keep it personal and safe."}],"register":"auto"}},{"type":"NewWorldPromises","props":{"id":"fh-training-agreements-1s","index":"05","eyebrow":"Read at every circle","title":"Six *agreements.*","lede":"","rows":[{"icon":"check","title":"Every practice is an invitation","body":"Join in, go gently, watch, or pass. No one needs a reason."},{"icon":"heart","title":"What is shared stays here","body":"Take the lessons home. Leave the stories and the names in the room."},{"icon":"users","title":"Speak for yourself","body":"Use I. Speak from your own life, not about anyone else''s."},{"icon":"message","title":"No fixing","body":"Listen without advising, correcting or rescuing. Ask an honest question, or simply say thank you."},{"icon":"calendar","title":"Start and end on time","body":"A clear start and a clear end are a kindness. People can plan around you."},{"icon":"award","title":"Ask before touch","body":"No touch without a clear yes, every time. Nothing sexual happens in a circle."}],"register":"auto"}},{"type":"NewWorldFirstVisit","props":{"id":"fh-training-care-1t","index":"06","eyebrow":"When something comes up","title":"Safe enough *to be honest.*","lede":"Our training follows the six principles of a trauma-informed approach: safety, trust and transparency, peer support, collaboration, choice and voice, and culture and context.","note":"A Frequency circle is practice and community, not therapy or crisis care. In the US, call or text 988 for the Suicide and Crisis Lifeline. If anyone is in immediate danger, call emergency services.","rows":[{"title":"Strong feelings","body":"Slow down. Let the person finish, thank them, and offer a breath for the whole circle. Tears aren''t an emergency."},{"title":"A disclosure","body":"Thank them, don''t press for details in the circle, and speak privately afterwards. Share the local crisis line."},{"title":"One voice filling the room","body":"Use the talking piece. Set a time per share before the round starts. Invite someone who hasn’t spoken yet."},{"title":"After a hard night","body":"Debrief with your co-host or mentor within a day. Hosting is a team practice."}],"register":"auto"}},{"type":"NewWorldCloser","props":{"id":"fh-closer-creator-lab-2f","aside":"Generous structure. Real care. On time.","title":"Start with *one course.*","primaryLabel":"The Business of Community","primaryHref":"/spaces/hq/business-of-community","secondaryLabel":"Start Host Foundations","secondaryHref":"/journeys/host-foundations","note":"","register":"auto"}}]},"seo":{"title":"Creator Lab · Frequency","description":"Creator Lab: free courses for the people who gather others. Hosting on the PULSE rhythm, and The Business of Community."},"comments":[]},{"slug":"business-of-community","label":"Business of Community","doc":{"root":{"props":{}},"content":[{"type":"PhotoHero","props":{"id":"boc-hero-0","variant":"image","display":"beside","height":"medium","scrim":"light","image":"/sites/new-world/photos/beach-joy.webp","alt":"Friends laughing together on a beach at golden hour","eyebrow":"Live workshop · Free","title":"People showed up once. Here’s how they come back.","accentWord":"Here’s how they come back.","subtitle":"The Business of Community is Frequency’s free four-week live workshop for anyone who gathers people. Four simple meetings you can run, all on the PULSE rhythm. It assumes you’re starting from scratch.","actionPrimaryLabel":"Save your seat","actionPrimaryHref":"/events/business-of-community-pilot-session-1","actionSecondaryLabel":"Join the January Run","actionSecondaryHref":"/circles/business-of-community-january-2027","note":"Thursdays, January 7 to 28 · 10 to 11:30 AM Pacific · on Zoom"}},{"type":"Zigzag","props":{"id":"boc-idea-1","image":"/sites/new-world/photos/circle-sunrise.webp","alt":"A small group sitting in a circle outdoors at sunrise","mediaSide":"right","background":"canvas","eyebrow":"The one idea","title":"Frequency. The how-often kind.","accentWord":"The how-often kind.","body":"lead","lead":"Most people who gather others count heads. How many came. How full it looked.<br><br>A community lives on a different number: how many came back. A small room where people return is healthier than a big room you never see again. That number runs through all four weeks.","items":[],"quoteBy":"","ctaLabel":"","ctaHref":""}},{"type":"CardGrid","props":{"id":"boc-weeks-2","role":"step","columns":2,"eyebrow":"The four weeks","title":"Four meetings you can run.","accentWord":"you can run.","cards":[{"title":"Jan 7 · The weekly sit-down","body":"A weekly 30-minute meeting with yourself that keeps you from carrying everything at once."},{"title":"Jan 14 · The opening","body":"An opening you can run every time: your purpose in one line, three agreements read aloud, and a check-in round."},{"title":"Jan 21 · The full gathering","body":"A one-page run sheet for a 90-minute gathering, and a ten-minute habit the next day to see who came back."},{"title":"Jan 28 · The money hour","body":"Your break-even number, one price you can say without flinching, and a monthly hour to keep both honest."}],"browseLabel":"","browseHref":""}},{"type":"Zigzag","props":{"id":"boc-week-3","image":"/sites/new-world/photos/workshop-table.webp","alt":"Adults and kids making crafts around a long table in a workshop room","mediaSide":"left","background":"accent-wash","eyebrow":"How each week works","title":"Read it. Practice it. Run it.","accentWord":"Run it.","body":"list","lead":"","items":[{"text":"Before Thursday, about 15 minutes: a short overview and one lesson."},{"text":"Thursday, 90 minutes live on Zoom, on PULSE: a story, check-ins in small groups, the meeting and a practice run, a moment to steady, and one commitment said out loud."},{"text":"After: run the meeting once with your own people, fill in your one page, and post a three-line report back to your Run."}],"quoteBy":"","ctaLabel":"Save your seat","ctaHref":"/events/business-of-community-pilot-session-1"}},{"type":"CardGrid","props":{"id":"boc-guides-4","role":"media","columns":2,"eyebrow":"Your guides","title":"Hosted by Frequency. Led by Daniel and Feargal.","accentWord":"Led by Daniel and Feargal.","cards":[{"image":"/brand/frequency/photos/guide-daniel-tyack.jpg","alt":"Daniel Tyack","title":"Daniel Tyack","body":"Founder of Frequency. Daniel has spent years building and leading rooms, from music to men’s work to ceremony, and created PULSE, the rhythm the workshop runs on."},{"image":"/brand/frequency/photos/guide-feargal-walsh.jpg","alt":"Feargal Walsh","title":"Feargal Walsh","body":"Leads technology and member experience at Frequency. Feargal turns the systems organizers need into tools that are simple to run week after week."}],"browseLabel":"","browseHref":""}},{"type":"CardGrid","props":{"id":"boc-ways-5","role":"feature","columns":2,"eyebrow":"Two ways in","title":"Four weeks together, then every week.","accentWord":"then every week.","cards":[{"icon":"◎","title":"The live workshop","body":"Free for anyone, Space or not. Four Thursdays on Zoom, 10 to 11:30 AM Pacific, several times a year. The launch Run meets January 7 to 28.","button":{"label":"Save your seat","href":"/events/business-of-community-pilot-session-1"}},{"icon":"↗","title":"Business Hours","body":"For Spaces on the Business plan. Wednesday mornings at 10 AM Pacific on Zoom, run on PULSE in a members-only Circle. Bring one number and one stuck thing.","button":{"label":"See the Circle","href":"/circles/business-hours"}}],"browseLabel":"See the Business plan","browseHref":"/pricing"}},{"type":"Zigzag","props":{"id":"boc-finish-6","image":"/sites/new-world/photos/fire-circle.webp","alt":"People sitting around a fire at dusk","mediaSide":"right","background":"canvas","eyebrow":"Two ways to finish","title":"Attended or Certified.","accentWord":"Certified.","body":"list","lead":"","items":[{"text":"Attended: come to all four live sessions."},{"text":"Certified: send in your Community Book, your four pages filled in from real gatherings. Review is free for Community Books submitted by February 28, 2027, then comes with the Business plan."},{"text":"Certified is a certificate of completion and competency from Frequency. It is not an accredited certification."}],"quoteBy":"","ctaLabel":"","ctaHref":""}},{"type":"EditorialSection","props":{"id":"boc-faq-7","eyebrow":"Questions","title":"Good to know.","accentWord":"know.","kicker":"Anything else, ask. A person on the Frequency team answers.","body":"faq","surface":"open","lead":"","stats":[],"faqs":[{"q":"What does it cost?","a":"Nothing. The workshop is free for anyone. Certified review is free for Community Books submitted by February 28, 2027, then comes with the Business plan."},{"q":"When is the next workshop?","a":"The launch Run meets Thursdays, 10 to 11:30 AM Pacific, on Zoom: January 7, 14, 21 and 28, 2027, the month Frequency launches. Anyone can join. Save your seat on the Week 1 event and the Zoom link comes to you. New Runs start through the year."},{"q":"How much time does it take?","a":"About three hours a week. Before Thursday, 15 minutes: a short overview and one lesson. Thursday, 90 minutes live. After, your homework: run that week’s meeting once with your own people and post a three-line report back."},{"q":"I haven’t started anything yet. Is it for me?","a":"Yes. It assumes you’re starting from scratch. If you run something already, you’ll fix the parts that wear you out."},{"q":"What is PULSE?","a":"The five-beat rhythm every Frequency gathering follows: Presence, Unite, Lead, Settle, Exhale. Every meeting in this workshop runs on it, and so does each session."},{"q":"Do I need a Space?","a":"No. Everything works on paper and a phone. If you have a Space, each week ends with an optional step to set it up there."},{"q":"What is Business Hours?","a":"A weekly hour on Zoom for Spaces on the Business plan, Wednesday mornings at 10 AM Pacific, run on PULSE in a members-only Circle. Bring one number and one stuck thing."},{"q":"Is it accredited?","a":"No. Certified is a certificate of completion and competency from Frequency, not an accredited certification."}]}},{"type":"AccentBeat","props":{"id":"boc-closer-8","mode":"cta","background":"accent-wash","image":"","alt":"","eyebrow":"Free · Four weeks · Live on Zoom","title":"Keep the room. Keep yourself.","accentWord":"Keep yourself.","body":"The launch Run starts Thursday, January 7.","quoteBy":"","ctaLabel":"Save your seat","ctaHref":"/events/business-of-community-pilot-session-1","ctaSecondaryLabel":"Ask a question","ctaSecondaryHref":"/spaces/hq/help"}}]},"seo":{"title":"The Business of Community 101 · Frequency","description":"Frequency’s free four-week live business workshop for anyone who gathers people. Four simple meetings on the PULSE rhythm, live on Zoom. Starts January 7, 2027."},"comments":[]},{"slug":"help","label":"Help desk","doc":{"root":{"props":{}},"content":[{"type":"NewWorldPageHead","props":{"id":"fh-help-head-22","index":"","eyebrow":"Help desk","title":"Ask. *A person answers.*","lede":"Open a help ticket, browse the help center, or ask the community. Every ticket is read by a real person on the Frequency team.","register":"auto"}},{"type":"NewWorldWayRows","props":{"id":"fh-help-rows-23","costLabel":"Cost","whenLabel":"Best for","buttonLabel":"Open a help ticket","buttonHref":"/support","secondaryLabel":"Common questions","secondaryHref":"#faq","rows":[{"icon":"message","tags":"Help desk","name":"Open a help ticket","body":"Tell us what happened. Follow every reply from your tickets.","price":"Free","when":"Your account, billing, bugs","image":"/sites/new-world/photos/cafe-table.webp","alt":"Three people talking at a small table in a cafe","buttonLabel":"Open a ticket","href":"/support"},{"icon":"check","tags":"Help center","name":"Browse the help center","body":"Plain answers on Circles, events, Spaces, The Quest and membership.","price":"Free","when":"How-to questions","image":"/sites/new-world/photos/garden-picnic.webp","alt":"People gathered on rugs and cushions in a leafy backyard garden","buttonLabel":"Open the help center","href":"/help"},{"icon":"users","tags":"Forum","name":"Ask the community","body":"Post a question or an idea. Members, hosts and the team answer.","price":"Free","when":"Ideas and how others do it","image":"/brand/frequency/photos/gathering-12.jpg","alt":"A tight group hugging and laughing on a seaside deck","buttonLabel":"Go to the forum","href":"/spaces/hq/community"},{"icon":"heart","tags":"Safety","name":"Report a safety concern","body":"Reporting, blocking and how moderation works. In an emergency, call emergency services first.","price":"Free","when":"Anything that feels unsafe","image":"/sites/new-world/photos/fire-circle.webp","alt":"People sitting quietly around a fire pit in the evening","buttonLabel":"Safety and reporting","href":"/help/safety"}],"register":"auto"}},{"type":"NewWorldPosts","props":{"id":"fh-help-center-24","index":"01","eyebrow":"Help center","title":"Find it *fast.*","lede":"Seven topics, written in plain words.","buttonLabel":"Open the help center","buttonHref":"/help","rows":[{"kind":"Start here","title":"Getting started: what Frequency is and how to find your people","meta":"","href":"/help/getting-started"},{"kind":"Groups","title":"Circles and events: how gatherings work","meta":"","href":"/help/groups"},{"kind":"Hosting","title":"Leading a Circle: start one, run the first night, keep it going","meta":"","href":"/help/leading"},{"kind":"Spaces","title":"Running a Space: the tools a Space gives you","meta":"","href":"/help/spaces"},{"kind":"The Quest","title":"Zaps, Gems, ranks and rewards","meta":"","href":"/help/the-quest"},{"kind":"Membership","title":"What''s free and what Crew adds","meta":"","href":"/help/membership"},{"kind":"Safety","title":"Reporting, blocking and how moderation works","meta":"","href":"/help/safety"}],"register":"auto"}},{"type":"NewWorldFaq","props":{"id":"fh-help-faq-25","index":"02","eyebrow":"Questions","title":"Good to *know.*","lede":"Still stuck? Open a ticket or email us.","phone":"","email":"hello@frequencylocal.com","hours":"","areasLabel":"","areas":[],"rows":[{"question":"How do I open a help ticket?","answer":"Go to Help and support, describe what happened, and send it. You can follow every reply from your tickets on the same page."},{"question":"Something feels unsafe. What do I do?","answer":"Use Report on the post, profile or event, or open a ticket marked safety. If anyone is in immediate danger, call emergency services first."},{"question":"I have a billing question.","answer":"Open a ticket and choose billing. Include the email on your account so we can find it quickly."},{"question":"How do I start a Space for my business or group?","answer":"Read Running a Space in the help center, then create one from the Spaces page. The help desk can walk you through it."},{"question":"Can I suggest a feature?","answer":"Yes, please. Post it in the community forum so others can add to it, or open a ticket if it is about your own account."}],"register":"auto"}},{"type":"NewWorldCloser","props":{"id":"fh-closer-help-26","aside":"Generous structure. Real care. On time.","title":"Still stuck? *Ask us.*","primaryLabel":"Open a help ticket","primaryHref":"/support","secondaryLabel":"Ask the community","secondaryHref":"/spaces/hq/community","note":"","register":"auto"}}]},"seo":{"title":"Help desk · Frequency","description":"Open a help ticket, browse the help center, or ask the community."},"comments":[]},{"slug":"about","label":"About","doc":{"root":{"props":{}},"content":[{"type":"NewWorldAboutHero","props":{"id":"fh-about-hero-27","eyebrow":"Our story · Frequency","title":"Build circles, *not walls.*","lead":"Frequency is a community collective that spreads town by town through local hosts. This Space is where the team shares the programs, the training, the answers and the conversation in the open.","chips":[{"icon":"check","text":"Free to start"},{"icon":"users","text":"Run with its members"},{"icon":"heart","text":"Care designed in"}],"primaryLabel":"Explore programs","primaryHref":"/spaces/hq/programs","secondaryLabel":"Ask the community","secondaryHref":"/spaces/hq/community","image":"/sites/new-world/photos/circle-sunrise.webp","alt":"A wide circle of people seated on a plaza at sunrise","name":"Daniel Tyack","role":"Founder","register":"auto"}},{"type":"NewWorldLongStory","props":{"id":"fh-about-roots-28","index":"01","eyebrow":"Where this comes from","title":"Old practices, *plain words.*","paragraphs":["Sitting in a circle and taking turns to speak is one of the oldest ways people have gathered. We did not invent it. We gave it a rhythm, PULSE, that a new host can learn in a week and a returning guest can trust.","Our host training draws on a few sources worth reading in full. The Way of Council, as taught by Jack Zimmerman and Virginia Coyle, gives us the talking piece and its intentions. Parker Palmer and the Center for Courage and Renewal give us touchstones for trustworthy space, like no fixing and honest, open questions. Priya Parker gives us generous authority: a host who protects, connects and equalizes the room. SAMHSA gives us the six principles of a trauma-informed approach.","Everything is written in plain words, because a host should be able to read an agreement aloud without explaining it."],"register":"auto"}},{"type":"NewWorldQuote","props":{"id":"fh-about-quote-29","label":"In Daniel’s words","quote":"The structure exists to serve the circle. The circle *governs the structure.*","by":"Daniel Tyack · Founder","register":"auto"}},{"type":"NewWorldTeam","props":{"id":"fh-about-team-2a","index":"02","eyebrow":"The team","title":"Who *runs this.*","lede":"","note":"Trained hosts join this list as they become mentors.","rows":[{"name":"Daniel Tyack","role":"Founder · The Janitor","image":"/brand/frequency/photos/daniel-tyack.jpg","alt":"Daniel Tyack smiling"}],"register":"auto"}},{"type":"NewWorldCloser","props":{"id":"fh-closer-about-2b","aside":"Generous structure. Real care. On time.","title":"Pick a door. *Come in.*","primaryLabel":"Ask the community","primaryHref":"/spaces/hq/community","secondaryLabel":"Get help","secondaryHref":"/support","note":"","register":"auto"}}]},"seo":{"title":"About · Frequency","description":"Frequency is a community collective. Build circles, not walls."},"comments":[]}]},"published":{"theme":"NewWorld","brand":{"logo":"/brand/frequency/logo/frequency-icon-round.png","accent":"#1AA7C0"},"chrome":{"name":"Frequency","tagline":"Gather like it matters.","cta":{"label":"Get help","href":"/support"}},"pages":[{"slug":"home","label":"Home","doc":{"root":{"props":{}},"content":[{"type":"NewWorldHero","props":{"id":"fh-home-hero-18","eyebrow":"Frequency · Programs, training and help","title":"Gather like it *matters.*","lead":"The home base for everyone building Frequency. Find our programs, learn to host on the PULSE rhythm, get help from a real person, and ask the community anything. Start wherever you are.","primaryLabel":"Explore programs","primaryHref":"/spaces/hq/programs","secondaryLabel":"Get help","secondaryHref":"/spaces/hq/help","proof":"Run by the Frequency team, for members, hosts and Spaces.","aside":"We build circles, not walls.","image":"/brand/frequency/photos/day-meditation-circle.jpg","alt":"A large circle of people seated on the grass by the ocean, eyes closed","badge":"Open to everyone","useEvents":true,"rows":[{"weekday":"Help","mon":"Desk","day":"1","title":"Open a help ticket","body":"A real person reads every ticket.","time":"Any time","where":"Online","spots":"Open","kind":"session","href":"/support"},{"weekday":"Workshop","mon":"Free","day":"2","title":"The Business of Community","body":"A free four-week live workshop on the PULSE rhythm. Starts January 7.","time":"4 weeks · live on Zoom","where":"Online","spots":"Open","kind":"session","href":"/events/business-of-community-pilot-session-1"},{"weekday":"Course","mon":"Free","day":"3","title":"Host Foundations","body":"Four short weeks on the craft every Frequency host shares: why we gather, the PULSE rhythm, setting the room, and running your first circle.","time":"Self-paced · 4 parts","where":"Online","spots":"Open","kind":"session","href":"/journeys/host-foundations"}],"register":"auto"}},{"type":"NewWorldStats","props":{"id":"fh-home-stats-19","items":[{"icon":"heart","value":"4","label":"Pillars","note":"Mind, Body, Spirit, Expression"},{"icon":"users","value":"5","label":"beats in every circle","note":"Presence, Unite, Lead, Settle, Exhale"},{"icon":"calendar","value":"4","label":"host courses","note":"Three free online, one in person"},{"icon":"check","value":"1","label":"help desk","note":"A real person answers"}],"register":"auto"}},{"type":"NewWorldPromises","props":{"id":"fh-home-doors-1a","index":"01","eyebrow":"Inside","title":"Five *doors.*","lede":"Everything the Frequency team runs for members, hosts and Spaces.","rows":[{"icon":"award","title":"Programs","body":"The Quest, Circles, events and host training: the structured ways to take part."},{"icon":"heart","title":"Host training","body":"Free courses on the PULSE rhythm, care and consent, and the three circle formats."},{"icon":"check","title":"Help desk","body":"Open a ticket, browse the help center, or report something that feels off."},{"icon":"sparkle","title":"Creator Lab","body":"Business and leadership for the people who gather others. Starts with The Business of Community 101."},{"icon":"users","title":"Community forum","body":"Ask a question, share what worked, suggest a feature. Hosts and the team read it."}],"register":"auto"}},{"type":"NewWorldStory","props":{"id":"fh-home-story-1b","index":"02","eyebrow":"A community collective","title":"Built by *its members.*","paragraphs":["Frequency is a community collective, not just an app. The software helps people find each other and helps local hosts and businesses run their rooms. The point is the room.","We grow town by town, one circle at a time. Every one of those circles needs someone who arrives early, sets the chairs, starts on time and makes the new person feel expected.","This Space is where that work is shared in the open: the programs, the training, the answers and the conversation."],"buttonLabel":"Our story","buttonHref":"/spaces/hq/about","secondaryLabel":"Ask the community","secondaryHref":"/spaces/hq/community","image":"/brand/frequency/photos/gathering-03.jpg","alt":"People gathered on rugs and cushions in a leafy garden","quote":"The structure exists to serve the circle.","quoteBy":"Daniel Tyack · Founder","register":"auto"}},{"type":"SpacePractices","props":{"id":"fh-home-journeys-1c","eyebrow":"Learn here","heading":"Courses to start","practicesHeading":"Practices","journeysHeading":"Courses","only":""}},{"type":"NewWorldProcess","props":{"id":"fh-home-path-1d","index":"03","eyebrow":"Host training","title":"From guest to *host.*","lede":"","rows":[{"icon":"calendar","title":"Learn","body":"Take Host Foundations, free and self-paced. Four short weeks on the PULSE rhythm."},{"icon":"heart","title":"Learn to care","body":"Take Safe and Well Held: agreements, consent and what to do when something comes up."},{"icon":"users","title":"Co-host","body":"Run two circles beside a trained host. Lead one beat, then two, then the whole night."},{"icon":"award","title":"Host","body":"Open your own circle with a mentor on call, then join the monthly Host Circle."}],"register":"auto"}},{"type":"NewWorldGallery","props":{"id":"fh-home-gallery-1e","index":"04","eyebrow":"Real circles","title":"Rooms people *come back to.*","lede":"Photos from Frequency gatherings.","images":[{"image":"/brand/frequency/photos/gathering-04.jpg","alt":"A circle seated on a lawn with arms stretched wide"},{"image":"/brand/frequency/photos/gathering-12.jpg","alt":"A tight group hugging and laughing on a seaside deck"},{"image":"/brand/frequency/photos/day-parachute-play.jpg","alt":"People holding a rainbow parachute on a clifftop lawn"},{"image":"/brand/frequency/photos/gathering-14.jpg","alt":"A circle on mats around a gong at the water"},{"image":"/brand/frequency/photos/gathering-13.jpg","alt":"A group moving together on the beach at golden hour"}],"register":"auto"}},{"type":"NewWorldFaq","props":{"id":"fh-home-faq-1f","index":"05","eyebrow":"Questions","title":"Good to *know.*","lede":"Anything else, ask. A real person answers.","phone":"","email":"hello@frequencylocal.com","hours":"","areasLabel":"","areas":[],"rows":[{"question":"What is this Space?","answer":"The Frequency team''s own Space: our programs, host training, Creator Lab, the help desk and a community forum, in one place. Follow it to hear what''s new."},{"question":"How do I get help with my account?","answer":"Open a help ticket from the help desk. A real person reads every one, and you can follow the reply from your tickets."},{"question":"Do I need experience to host?","answer":"No. Most Frequency hosts started as guests. Host Foundations and the apprenticeship take you from your first seat in the circle to running your own."},{"question":"Can my organization train its own hosts here?","answer":"Yes. The courses and the PULSE rhythm are built so partner organizations and volunteers can use them for their own in-person and online groups."},{"question":"Where do I ask other members a question?","answer":"In the community forum. Post a question, share what worked, or say hello. Hosts and the team read it too."}],"register":"auto"}},{"type":"NewWorldCloser","props":{"id":"fh-closer-home-1g","aside":"Generous structure. Real care. On time.","title":"Pick a door. *Come in.*","primaryLabel":"Ask the community","primaryHref":"/spaces/hq/community","secondaryLabel":"Get help","secondaryHref":"/support","note":"","register":"auto"}}]},"seo":{"title":"Frequency","description":"Frequency: programs, free host training, Creator Lab, a help desk and a community forum."},"comments":[]},{"slug":"programs","label":"Programs","doc":{"root":{"props":{}},"content":[{"type":"NewWorldPageHead","props":{"id":"fh-programs-head-1h","index":"","eyebrow":"Frequency Programs","title":"Show up. *Come back.*","lede":"Frequency Programs are the structured ways to take part: The Quest, Circles, local events and host training. Start with one.","register":"auto"}},{"type":"NewWorldWayRows","props":{"id":"fh-programs-rows-1i","costLabel":"For","whenLabel":"Rhythm","buttonLabel":"Start","buttonHref":"/circles","secondaryLabel":"Questions","secondaryHref":"/spaces/hq/help","rows":[{"icon":"award","tags":"Program","name":"The Quest","body":"Daily practices and Journeys you take with your Circle, across the four Pillars. Show up, earn Zaps and Gems, and climb the season.","price":"Every member","when":"Daily","image":"/brand/frequency/photos/gathering-13.jpg","alt":"A group moving together on the beach at golden hour","buttonLabel":"How The Quest works","href":"/help/the-quest"},{"icon":"users","tags":"Program","name":"Circles","body":"Small groups of 12 to 18 people who meet at the same time in the same place, on the PULSE rhythm.","price":"Every member","when":"Weekly or every other week","image":"/brand/frequency/photos/gathering-04.jpg","alt":"A circle seated on a lawn with arms stretched wide","buttonLabel":"Find a Circle","href":"/circles"},{"icon":"calendar","tags":"Program","name":"What''s happening","body":"Local events from Circles and Spaces near you. RSVP, add it to your calendar, bring someone.","price":"Everyone","when":"Any week","image":"/brand/frequency/photos/day-parachute-play.jpg","alt":"People holding a rainbow parachute on a clifftop lawn","buttonLabel":"See what''s happening","href":"/events"},{"icon":"sparkle","tags":"Program","name":"Creator Lab","body":"Core training for the people who gather others. The Business of Community is a free four-week live workshop on Zoom, run several times a year; the Business plan adds Business Hours on Zoom.","price":"Anyone","when":"One week at a time","image":"/brand/frequency/photos/gathering-03.jpg","alt":"People gathered on rugs and cushions in a leafy garden","buttonLabel":"Open Creator Lab","href":"/spaces/hq/creator-lab"},{"icon":"heart","tags":"Program","name":"Host training","body":"Free courses on the PULSE rhythm, care and consent, and the three circle formats, then a co-host apprenticeship.","price":"Hosts and future hosts","when":"Self-paced","image":"/brand/frequency/photos/day-meditation-circle.jpg","alt":"A large circle of people seated on the grass by the ocean, eyes closed","buttonLabel":"Start host training","href":"/spaces/hq/creator-lab"}],"register":"auto"}},{"type":"NewWorldPromises","props":{"id":"fh-programs-pillars-1j","index":"01","eyebrow":"The Quest","title":"Four *Pillars.*","lede":"Every practice and Journey sits under one Pillar, so you build the same strengths all year in different forms.","rows":[{"icon":"sparkle","title":"Mind","body":"Calm down fast, focus, and think clearly. Practices like breathing, journaling and less scrolling."},{"icon":"heart","title":"Body","body":"Move, rest, eat and sleep like you mean it. Walks, stretching, cold water, early nights."},{"icon":"users","title":"Spirit","body":"Meaning, gratitude and time with people. Stillness, service and showing up for each other."},{"icon":"award","title":"Expression","body":"Make something and share it. The weekly Expression Challenge, alone or with your Circle."}],"register":"auto"}},{"type":"NewWorldProcess","props":{"id":"fh-programs-quest-1k","index":"02","eyebrow":"How The Quest works","title":"Small things, *every day.*","lede":"","rows":[{"icon":"calendar","title":"Pick a Journey","body":"Choose one under a Pillar. Each has a few minutes of practice a day."},{"icon":"check","title":"Practice daily","body":"Log it when you do it. Streaks build, and misses are part of it."},{"icon":"users","title":"Bring your Circle","body":"Take a Journey with your Circle and show up for each other in person."},{"icon":"award","title":"Earn as you go","body":"Zaps and Gems for showing up, a Pillar Trophy when you finish a Journey."}],"register":"auto"}},{"type":"NewWorldCloser","props":{"id":"fh-closer-programs-1l","aside":"Generous structure. Real care. On time.","title":"Start with *one.*","primaryLabel":"Find a Circle","primaryHref":"/circles","secondaryLabel":"See what''s happening","secondaryHref":"/events","note":"","register":"auto"}}]},"seo":{"title":"Programs · Frequency","description":"Frequency Programs: The Quest, Circles, local events and host training."},"comments":[]},{"slug":"creator-lab","label":"Creator Lab","doc":{"root":{"props":{}},"content":[{"type":"NewWorldPageHead","props":{"id":"fh-lib-head-2c","index":"","eyebrow":"Creator Lab","title":"Courses for the people who *gather others.*","lede":"Free courses in two tracks: hosting the room, and running the community behind it. Start anywhere. Every course ends with you doing it for real.","register":"auto"}},{"type":"NewWorldPromises","props":{"id":"fh-lib-tracks-2d","index":"01","eyebrow":"The library","title":"Two *tracks.*","lede":"Each course is free. The Business plan adds a weekly room on Zoom.","rows":[{"icon":"heart","title":"Hosting","body":"The PULSE rhythm, care and consent, the three circle formats, and an apprenticeship beside a trained host."},{"icon":"sparkle","title":"Business and leadership","body":"The Business of Community: four simple meetings on PULSE that bring people back, and keep you going."}],"register":"auto"}},{"type":"NewWorldWayRows","props":{"id":"fh-lib-rows-2e","costLabel":"Cost","whenLabel":"Length","buttonLabel":"Start a course","buttonHref":"/spaces/hq/business-of-community","secondaryLabel":"Questions","secondaryHref":"/spaces/hq/help","rows":[{"icon":"calendar","tags":"Business · 4 weeks","name":"The Business of Community","body":"Frequency’s free live workshop. Four 90-minute sessions on Zoom, all on PULSE: the weekly sit-down, the opening, the full gathering and the money hour. Short lessons to read before each one.","price":"Free","when":"4 weeks","image":"/brand/frequency/photos/gathering-04.jpg","alt":"A circle seated on a lawn with arms stretched wide","buttonLabel":"See the workshop","href":"/spaces/hq/business-of-community"},{"icon":"users","tags":"Business · January Run","name":"The January Run","body":"Everyone in the launch Run, together. A thread to share what you tried between sessions, and someone noticing when you don’t show. Thursdays Jan 7, 14, 21 and 28.","price":"Free","when":"Starts January 7","image":"/brand/frequency/photos/gathering-12.jpg","alt":"A tight group hugging and laughing on a seaside deck","buttonLabel":"Join the Run","href":"/circles/business-of-community-january-2027"},{"icon":"message","tags":"Business · Zoom","name":"Business Hours","body":"Same hour every week, run on PULSE. Bring one number and one stuck thing. Last week’s commitments read back, one hot seat, and a new commitment each.","price":"Business plan","when":"Wednesdays · 10 AM Pacific","image":"/sites/new-world/photos/cafe-table.webp","alt":"Three people talking at a small table in a cafe","buttonLabel":"See the Circle","href":"/circles/business-hours"},{"icon":"calendar","tags":"Hosting · Online","name":"Host Foundations","body":"Four short weeks on the craft every Frequency host shares: why we gather, the PULSE rhythm, setting the room, and running your first circle.","price":"Free","when":"4 parts","image":"/brand/frequency/photos/day-meditation-circle.jpg","alt":"","buttonLabel":"Start the course","href":"/journeys/host-foundations"},{"icon":"heart","tags":"Hosting · Online","name":"Safe and Well Held","body":"Agreements, consent and care: how to keep a room safe enough to be honest, and what to do when something comes up.","price":"Free","when":"4 parts","image":"/brand/frequency/photos/gathering-12.jpg","alt":"","buttonLabel":"Start the course","href":"/journeys/safe-and-well-held"},{"icon":"users","tags":"Hosting · Online","name":"The Three Circle Formats","body":"Open, Community and Focus Circles: what each one is for, what the host does, and how to choose.","price":"Free","when":"4 parts","image":"/brand/frequency/photos/gathering-03.jpg","alt":"","buttonLabel":"Start the course","href":"/journeys/circle-formats"},{"icon":"award","tags":"Hosting · In person","name":"Co-host Apprenticeship","body":"Learn by doing: shadow a trained host, co-lead two circles, then host your own with a mentor on call.","price":"Ask us","when":"Three circles","image":"/brand/frequency/photos/gathering-04.jpg","alt":"","buttonLabel":"Ask about a mentor","href":"/journeys/co-host-apprenticeship"}],"register":"auto"}},{"type":"NewWorldProcess","props":{"id":"fh-pulse-beats-1p","index":"02","eyebrow":"The PULSE rhythm · for everyone","title":"What each beat *is.*","lede":"","rows":[{"icon":"heart","title":"P · Presence","body":"Arrive. A few slow breaths, feet on the floor, phones away. The host sets the tone by going first."},{"icon":"users","title":"U · Unite","body":"A check-in round. Each person says how they''re arriving, and everyone else listens without replying."},{"icon":"award","title":"L · Lead","body":"Tonight''s practice: a teaching, a movement, a conversation or a skill. The part that changes from week to week."},{"icon":"check","title":"S · Settle","body":"Quiet integration. Rest, journal or sit with what came up before anyone has to talk about it."},{"icon":"message","title":"E · Exhale","body":"Close together. One word or one line each, a thank you, and a clear end."}],"register":"auto"}},{"type":"NewWorldFirstVisit","props":{"id":"fh-pulse-host-1q","index":"03","eyebrow":"The PULSE rhythm · for the host","title":"What you *do.*","lede":"A 90-minute night, beat by beat.","note":"Shorter night? Trim Lead first. Never skip Exhale.","rows":[{"title":"Presence · 10 min","body":"Start on time. Welcome people by name. Name the purpose of tonight in one sentence."},{"title":"Unite · 20 min","body":"Read the agreements. Ask one question everyone can answer. Keep it lean so everyone gets a turn."},{"title":"Lead · 35 min","body":"Give clear steps, an invitation and an opt-out. Watch the room more than your notes."},{"title":"Settle · 15 min","body":"Lower the pace. Offer a simple prompt. Let silence do some of the work."},{"title":"Exhale · 10 min","body":"End on time. Say what happens next and how people can reach you."}],"register":"auto"}},{"type":"NewWorldPromises","props":{"id":"fh-training-formats-1r","index":"04","eyebrow":"One rhythm","title":"Three *formats.*","lede":"Every circle runs on PULSE. The format decides how much you teach and how big the room gets.","rows":[{"icon":"users","title":"Open Circle · 12 to 18 people","body":"The host keeps the room, with no teaching agenda. People come to be heard and to hear each other. You open and close, keep the agreements and the time, and pass the turn. You speak least."},{"icon":"heart","title":"Community Circle · 12 to 18 people","body":"A hosted circle around one shared theme: moon circles, men''s and women''s circles, grief, new parents, sharing circles. You choose the theme and the question for the round, and keep the circle on it."},{"icon":"award","title":"Focus Circle · Up to 50 people","body":"The host teaches a modality: breathwork, sound, movement, a skill. The PULSE rhythm wraps the teaching so the room still feels like a circle. You teach in the Lead beat, and the four beats around it keep it personal and safe."}],"register":"auto"}},{"type":"NewWorldPromises","props":{"id":"fh-training-agreements-1s","index":"05","eyebrow":"Read at every circle","title":"Six *agreements.*","lede":"","rows":[{"icon":"check","title":"Every practice is an invitation","body":"Join in, go gently, watch, or pass. No one needs a reason."},{"icon":"heart","title":"What is shared stays here","body":"Take the lessons home. Leave the stories and the names in the room."},{"icon":"users","title":"Speak for yourself","body":"Use I. Speak from your own life, not about anyone else''s."},{"icon":"message","title":"No fixing","body":"Listen without advising, correcting or rescuing. Ask an honest question, or simply say thank you."},{"icon":"calendar","title":"Start and end on time","body":"A clear start and a clear end are a kindness. People can plan around you."},{"icon":"award","title":"Ask before touch","body":"No touch without a clear yes, every time. Nothing sexual happens in a circle."}],"register":"auto"}},{"type":"NewWorldFirstVisit","props":{"id":"fh-training-care-1t","index":"06","eyebrow":"When something comes up","title":"Safe enough *to be honest.*","lede":"Our training follows the six principles of a trauma-informed approach: safety, trust and transparency, peer support, collaboration, choice and voice, and culture and context.","note":"A Frequency circle is practice and community, not therapy or crisis care. In the US, call or text 988 for the Suicide and Crisis Lifeline. If anyone is in immediate danger, call emergency services.","rows":[{"title":"Strong feelings","body":"Slow down. Let the person finish, thank them, and offer a breath for the whole circle. Tears aren''t an emergency."},{"title":"A disclosure","body":"Thank them, don''t press for details in the circle, and speak privately afterwards. Share the local crisis line."},{"title":"One voice filling the room","body":"Use the talking piece. Set a time per share before the round starts. Invite someone who hasn’t spoken yet."},{"title":"After a hard night","body":"Debrief with your co-host or mentor within a day. Hosting is a team practice."}],"register":"auto"}},{"type":"NewWorldCloser","props":{"id":"fh-closer-creator-lab-2f","aside":"Generous structure. Real care. On time.","title":"Start with *one course.*","primaryLabel":"The Business of Community","primaryHref":"/spaces/hq/business-of-community","secondaryLabel":"Start Host Foundations","secondaryHref":"/journeys/host-foundations","note":"","register":"auto"}}]},"seo":{"title":"Creator Lab · Frequency","description":"Creator Lab: free courses for the people who gather others. Hosting on the PULSE rhythm, and The Business of Community."},"comments":[]},{"slug":"business-of-community","label":"Business of Community","doc":{"root":{"props":{}},"content":[{"type":"PhotoHero","props":{"id":"boc-hero-0","variant":"image","display":"beside","height":"medium","scrim":"light","image":"/sites/new-world/photos/beach-joy.webp","alt":"Friends laughing together on a beach at golden hour","eyebrow":"Live workshop · Free","title":"People showed up once. Here’s how they come back.","accentWord":"Here’s how they come back.","subtitle":"The Business of Community is Frequency’s free four-week live workshop for anyone who gathers people. Four simple meetings you can run, all on the PULSE rhythm. It assumes you’re starting from scratch.","actionPrimaryLabel":"Save your seat","actionPrimaryHref":"/events/business-of-community-pilot-session-1","actionSecondaryLabel":"Join the January Run","actionSecondaryHref":"/circles/business-of-community-january-2027","note":"Thursdays, January 7 to 28 · 10 to 11:30 AM Pacific · on Zoom"}},{"type":"Zigzag","props":{"id":"boc-idea-1","image":"/sites/new-world/photos/circle-sunrise.webp","alt":"A small group sitting in a circle outdoors at sunrise","mediaSide":"right","background":"canvas","eyebrow":"The one idea","title":"Frequency. The how-often kind.","accentWord":"The how-often kind.","body":"lead","lead":"Most people who gather others count heads. How many came. How full it looked.<br><br>A community lives on a different number: how many came back. A small room where people return is healthier than a big room you never see again. That number runs through all four weeks.","items":[],"quoteBy":"","ctaLabel":"","ctaHref":""}},{"type":"CardGrid","props":{"id":"boc-weeks-2","role":"step","columns":2,"eyebrow":"The four weeks","title":"Four meetings you can run.","accentWord":"you can run.","cards":[{"title":"Jan 7 · The weekly sit-down","body":"A weekly 30-minute meeting with yourself that keeps you from carrying everything at once."},{"title":"Jan 14 · The opening","body":"An opening you can run every time: your purpose in one line, three agreements read aloud, and a check-in round."},{"title":"Jan 21 · The full gathering","body":"A one-page run sheet for a 90-minute gathering, and a ten-minute habit the next day to see who came back."},{"title":"Jan 28 · The money hour","body":"Your break-even number, one price you can say without flinching, and a monthly hour to keep both honest."}],"browseLabel":"","browseHref":""}},{"type":"Zigzag","props":{"id":"boc-week-3","image":"/sites/new-world/photos/workshop-table.webp","alt":"Adults and kids making crafts around a long table in a workshop room","mediaSide":"left","background":"accent-wash","eyebrow":"How each week works","title":"Read it. Practice it. Run it.","accentWord":"Run it.","body":"list","lead":"","items":[{"text":"Before Thursday, about 15 minutes: a short overview and one lesson."},{"text":"Thursday, 90 minutes live on Zoom, on PULSE: a story, check-ins in small groups, the meeting and a practice run, a moment to steady, and one commitment said out loud."},{"text":"After: run the meeting once with your own people, fill in your one page, and post a three-line report back to your Run."}],"quoteBy":"","ctaLabel":"Save your seat","ctaHref":"/events/business-of-community-pilot-session-1"}},{"type":"CardGrid","props":{"id":"boc-guides-4","role":"media","columns":2,"eyebrow":"Your guides","title":"Hosted by Frequency. Led by Daniel and Feargal.","accentWord":"Led by Daniel and Feargal.","cards":[{"image":"/brand/frequency/photos/guide-daniel-tyack.jpg","alt":"Daniel Tyack","title":"Daniel Tyack","body":"Founder of Frequency. Daniel has spent years building and leading rooms, from music to men’s work to ceremony, and created PULSE, the rhythm the workshop runs on."},{"image":"/brand/frequency/photos/guide-feargal-walsh.jpg","alt":"Feargal Walsh","title":"Feargal Walsh","body":"Leads technology and member experience at Frequency. Feargal turns the systems organizers need into tools that are simple to run week after week."}],"browseLabel":"","browseHref":""}},{"type":"CardGrid","props":{"id":"boc-ways-5","role":"feature","columns":2,"eyebrow":"Two ways in","title":"Four weeks together, then every week.","accentWord":"then every week.","cards":[{"icon":"◎","title":"The live workshop","body":"Free for anyone, Space or not. Four Thursdays on Zoom, 10 to 11:30 AM Pacific, several times a year. The launch Run meets January 7 to 28.","button":{"label":"Save your seat","href":"/events/business-of-community-pilot-session-1"}},{"icon":"↗","title":"Business Hours","body":"For Spaces on the Business plan. Wednesday mornings at 10 AM Pacific on Zoom, run on PULSE in a members-only Circle. Bring one number and one stuck thing.","button":{"label":"See the Circle","href":"/circles/business-hours"}}],"browseLabel":"See the Business plan","browseHref":"/pricing"}},{"type":"Zigzag","props":{"id":"boc-finish-6","image":"/sites/new-world/photos/fire-circle.webp","alt":"People sitting around a fire at dusk","mediaSide":"right","background":"canvas","eyebrow":"Two ways to finish","title":"Attended or Certified.","accentWord":"Certified.","body":"list","lead":"","items":[{"text":"Attended: come to all four live sessions."},{"text":"Certified: send in your Community Book, your four pages filled in from real gatherings. Review is free for Community Books submitted by February 28, 2027, then comes with the Business plan."},{"text":"Certified is a certificate of completion and competency from Frequency. It is not an accredited certification."}],"quoteBy":"","ctaLabel":"","ctaHref":""}},{"type":"EditorialSection","props":{"id":"boc-faq-7","eyebrow":"Questions","title":"Good to know.","accentWord":"know.","kicker":"Anything else, ask. A person on the Frequency team answers.","body":"faq","surface":"open","lead":"","stats":[],"faqs":[{"q":"What does it cost?","a":"Nothing. The workshop is free for anyone. Certified review is free for Community Books submitted by February 28, 2027, then comes with the Business plan."},{"q":"When is the next workshop?","a":"The launch Run meets Thursdays, 10 to 11:30 AM Pacific, on Zoom: January 7, 14, 21 and 28, 2027, the month Frequency launches. Anyone can join. Save your seat on the Week 1 event and the Zoom link comes to you. New Runs start through the year."},{"q":"How much time does it take?","a":"About three hours a week. Before Thursday, 15 minutes: a short overview and one lesson. Thursday, 90 minutes live. After, your homework: run that week’s meeting once with your own people and post a three-line report back."},{"q":"I haven’t started anything yet. Is it for me?","a":"Yes. It assumes you’re starting from scratch. If you run something already, you’ll fix the parts that wear you out."},{"q":"What is PULSE?","a":"The five-beat rhythm every Frequency gathering follows: Presence, Unite, Lead, Settle, Exhale. Every meeting in this workshop runs on it, and so does each session."},{"q":"Do I need a Space?","a":"No. Everything works on paper and a phone. If you have a Space, each week ends with an optional step to set it up there."},{"q":"What is Business Hours?","a":"A weekly hour on Zoom for Spaces on the Business plan, Wednesday mornings at 10 AM Pacific, run on PULSE in a members-only Circle. Bring one number and one stuck thing."},{"q":"Is it accredited?","a":"No. Certified is a certificate of completion and competency from Frequency, not an accredited certification."}]}},{"type":"AccentBeat","props":{"id":"boc-closer-8","mode":"cta","background":"accent-wash","image":"","alt":"","eyebrow":"Free · Four weeks · Live on Zoom","title":"Keep the room. Keep yourself.","accentWord":"Keep yourself.","body":"The launch Run starts Thursday, January 7.","quoteBy":"","ctaLabel":"Save your seat","ctaHref":"/events/business-of-community-pilot-session-1","ctaSecondaryLabel":"Ask a question","ctaSecondaryHref":"/spaces/hq/help"}}]},"seo":{"title":"The Business of Community 101 · Frequency","description":"Frequency’s free four-week live business workshop for anyone who gathers people. Four simple meetings on the PULSE rhythm, live on Zoom. Starts January 7, 2027."},"comments":[]},{"slug":"help","label":"Help desk","doc":{"root":{"props":{}},"content":[{"type":"NewWorldPageHead","props":{"id":"fh-help-head-22","index":"","eyebrow":"Help desk","title":"Ask. *A person answers.*","lede":"Open a help ticket, browse the help center, or ask the community. Every ticket is read by a real person on the Frequency team.","register":"auto"}},{"type":"NewWorldWayRows","props":{"id":"fh-help-rows-23","costLabel":"Cost","whenLabel":"Best for","buttonLabel":"Open a help ticket","buttonHref":"/support","secondaryLabel":"Common questions","secondaryHref":"#faq","rows":[{"icon":"message","tags":"Help desk","name":"Open a help ticket","body":"Tell us what happened. Follow every reply from your tickets.","price":"Free","when":"Your account, billing, bugs","image":"/sites/new-world/photos/cafe-table.webp","alt":"Three people talking at a small table in a cafe","buttonLabel":"Open a ticket","href":"/support"},{"icon":"check","tags":"Help center","name":"Browse the help center","body":"Plain answers on Circles, events, Spaces, The Quest and membership.","price":"Free","when":"How-to questions","image":"/sites/new-world/photos/garden-picnic.webp","alt":"People gathered on rugs and cushions in a leafy backyard garden","buttonLabel":"Open the help center","href":"/help"},{"icon":"users","tags":"Forum","name":"Ask the community","body":"Post a question or an idea. Members, hosts and the team answer.","price":"Free","when":"Ideas and how others do it","image":"/brand/frequency/photos/gathering-12.jpg","alt":"A tight group hugging and laughing on a seaside deck","buttonLabel":"Go to the forum","href":"/spaces/hq/community"},{"icon":"heart","tags":"Safety","name":"Report a safety concern","body":"Reporting, blocking and how moderation works. In an emergency, call emergency services first.","price":"Free","when":"Anything that feels unsafe","image":"/sites/new-world/photos/fire-circle.webp","alt":"People sitting quietly around a fire pit in the evening","buttonLabel":"Safety and reporting","href":"/help/safety"}],"register":"auto"}},{"type":"NewWorldPosts","props":{"id":"fh-help-center-24","index":"01","eyebrow":"Help center","title":"Find it *fast.*","lede":"Seven topics, written in plain words.","buttonLabel":"Open the help center","buttonHref":"/help","rows":[{"kind":"Start here","title":"Getting started: what Frequency is and how to find your people","meta":"","href":"/help/getting-started"},{"kind":"Groups","title":"Circles and events: how gatherings work","meta":"","href":"/help/groups"},{"kind":"Hosting","title":"Leading a Circle: start one, run the first night, keep it going","meta":"","href":"/help/leading"},{"kind":"Spaces","title":"Running a Space: the tools a Space gives you","meta":"","href":"/help/spaces"},{"kind":"The Quest","title":"Zaps, Gems, ranks and rewards","meta":"","href":"/help/the-quest"},{"kind":"Membership","title":"What''s free and what Crew adds","meta":"","href":"/help/membership"},{"kind":"Safety","title":"Reporting, blocking and how moderation works","meta":"","href":"/help/safety"}],"register":"auto"}},{"type":"NewWorldFaq","props":{"id":"fh-help-faq-25","index":"02","eyebrow":"Questions","title":"Good to *know.*","lede":"Still stuck? Open a ticket or email us.","phone":"","email":"hello@frequencylocal.com","hours":"","areasLabel":"","areas":[],"rows":[{"question":"How do I open a help ticket?","answer":"Go to Help and support, describe what happened, and send it. You can follow every reply from your tickets on the same page."},{"question":"Something feels unsafe. What do I do?","answer":"Use Report on the post, profile or event, or open a ticket marked safety. If anyone is in immediate danger, call emergency services first."},{"question":"I have a billing question.","answer":"Open a ticket and choose billing. Include the email on your account so we can find it quickly."},{"question":"How do I start a Space for my business or group?","answer":"Read Running a Space in the help center, then create one from the Spaces page. The help desk can walk you through it."},{"question":"Can I suggest a feature?","answer":"Yes, please. Post it in the community forum so others can add to it, or open a ticket if it is about your own account."}],"register":"auto"}},{"type":"NewWorldCloser","props":{"id":"fh-closer-help-26","aside":"Generous structure. Real care. On time.","title":"Still stuck? *Ask us.*","primaryLabel":"Open a help ticket","primaryHref":"/support","secondaryLabel":"Ask the community","secondaryHref":"/spaces/hq/community","note":"","register":"auto"}}]},"seo":{"title":"Help desk · Frequency","description":"Open a help ticket, browse the help center, or ask the community."},"comments":[]},{"slug":"about","label":"About","doc":{"root":{"props":{}},"content":[{"type":"NewWorldAboutHero","props":{"id":"fh-about-hero-27","eyebrow":"Our story · Frequency","title":"Build circles, *not walls.*","lead":"Frequency is a community collective that spreads town by town through local hosts. This Space is where the team shares the programs, the training, the answers and the conversation in the open.","chips":[{"icon":"check","text":"Free to start"},{"icon":"users","text":"Run with its members"},{"icon":"heart","text":"Care designed in"}],"primaryLabel":"Explore programs","primaryHref":"/spaces/hq/programs","secondaryLabel":"Ask the community","secondaryHref":"/spaces/hq/community","image":"/sites/new-world/photos/circle-sunrise.webp","alt":"A wide circle of people seated on a plaza at sunrise","name":"Daniel Tyack","role":"Founder","register":"auto"}},{"type":"NewWorldLongStory","props":{"id":"fh-about-roots-28","index":"01","eyebrow":"Where this comes from","title":"Old practices, *plain words.*","paragraphs":["Sitting in a circle and taking turns to speak is one of the oldest ways people have gathered. We did not invent it. We gave it a rhythm, PULSE, that a new host can learn in a week and a returning guest can trust.","Our host training draws on a few sources worth reading in full. The Way of Council, as taught by Jack Zimmerman and Virginia Coyle, gives us the talking piece and its intentions. Parker Palmer and the Center for Courage and Renewal give us touchstones for trustworthy space, like no fixing and honest, open questions. Priya Parker gives us generous authority: a host who protects, connects and equalizes the room. SAMHSA gives us the six principles of a trauma-informed approach.","Everything is written in plain words, because a host should be able to read an agreement aloud without explaining it."],"register":"auto"}},{"type":"NewWorldQuote","props":{"id":"fh-about-quote-29","label":"In Daniel’s words","quote":"The structure exists to serve the circle. The circle *governs the structure.*","by":"Daniel Tyack · Founder","register":"auto"}},{"type":"NewWorldTeam","props":{"id":"fh-about-team-2a","index":"02","eyebrow":"The team","title":"Who *runs this.*","lede":"","note":"Trained hosts join this list as they become mentors.","rows":[{"name":"Daniel Tyack","role":"Founder · The Janitor","image":"/brand/frequency/photos/daniel-tyack.jpg","alt":"Daniel Tyack smiling"}],"register":"auto"}},{"type":"NewWorldCloser","props":{"id":"fh-closer-about-2b","aside":"Generous structure. Real care. On time.","title":"Pick a door. *Come in.*","primaryLabel":"Ask the community","primaryHref":"/spaces/hq/community","secondaryLabel":"Get help","secondaryHref":"/support","note":"","register":"auto"}}]},"seo":{"title":"About · Frequency","description":"Frequency is a community collective. Build circles, not walls."},"comments":[]}]},"scheduled":null,"versions":[{"id":"1","createdAt":"2026-11-18T05:08:20.207Z","author":"Frequency","snapshot":{"theme":"NewWorld","brand":{"logo":"/brand/frequency/logo/frequency-icon-round.png","accent":"#1AA7C0"},"chrome":{"name":"Frequency","tagline":"Gather like it matters.","cta":{"label":"Get help","href":"/support"}},"pages":[{"slug":"home","label":"Home","doc":{"root":{"props":{}},"content":[{"type":"NewWorldHero","props":{"id":"fh-home-hero-18","eyebrow":"Frequency · Programs, training and help","title":"Gather like it *matters.*","lead":"The home base for everyone building Frequency. Find our programs, learn to host on the PULSE rhythm, get help from a real person, and ask the community anything. Start wherever you are.","primaryLabel":"Explore programs","primaryHref":"/spaces/hq/programs","secondaryLabel":"Get help","secondaryHref":"/spaces/hq/help","proof":"Run by the Frequency team, for members, hosts and Spaces.","aside":"We build circles, not walls.","image":"/brand/frequency/photos/day-meditation-circle.jpg","alt":"A large circle of people seated on the grass by the ocean, eyes closed","badge":"Open to everyone","useEvents":true,"rows":[{"weekday":"Help","mon":"Desk","day":"1","title":"Open a help ticket","body":"A real person reads every ticket.","time":"Any time","where":"Online","spots":"Open","kind":"session","href":"/support"},{"weekday":"Workshop","mon":"Free","day":"2","title":"The Business of Community","body":"A free four-week live workshop on the PULSE rhythm. Starts January 7.","time":"4 weeks · live on Zoom","where":"Online","spots":"Open","kind":"session","href":"/events/business-of-community-pilot-session-1"},{"weekday":"Course","mon":"Free","day":"3","title":"Host Foundations","body":"Four short weeks on the craft every Frequency host shares: why we gather, the PULSE rhythm, setting the room, and running your first circle.","time":"Self-paced · 4 parts","where":"Online","spots":"Open","kind":"session","href":"/journeys/host-foundations"}],"register":"auto"}},{"type":"NewWorldStats","props":{"id":"fh-home-stats-19","items":[{"icon":"heart","value":"4","label":"Pillars","note":"Mind, Body, Spirit, Expression"},{"icon":"users","value":"5","label":"beats in every circle","note":"Presence, Unite, Lead, Settle, Exhale"},{"icon":"calendar","value":"4","label":"host courses","note":"Three free online, one in person"},{"icon":"check","value":"1","label":"help desk","note":"A real person answers"}],"register":"auto"}},{"type":"NewWorldPromises","props":{"id":"fh-home-doors-1a","index":"01","eyebrow":"Inside","title":"Five *doors.*","lede":"Everything the Frequency team runs for members, hosts and Spaces.","rows":[{"icon":"award","title":"Programs","body":"The Quest, Circles, events and host training: the structured ways to take part."},{"icon":"heart","title":"Host training","body":"Free courses on the PULSE rhythm, care and consent, and the three circle formats."},{"icon":"check","title":"Help desk","body":"Open a ticket, browse the help center, or report something that feels off."},{"icon":"sparkle","title":"Creator Lab","body":"Business and leadership for the people who gather others. Starts with The Business of Community 101."},{"icon":"users","title":"Community forum","body":"Ask a question, share what worked, suggest a feature. Hosts and the team read it."}],"register":"auto"}},{"type":"NewWorldStory","props":{"id":"fh-home-story-1b","index":"02","eyebrow":"A community collective","title":"Built by *its members.*","paragraphs":["Frequency is a community collective, not just an app. The software helps people find each other and helps local hosts and businesses run their rooms. The point is the room.","We grow town by town, one circle at a time. Every one of those circles needs someone who arrives early, sets the chairs, starts on time and makes the new person feel expected.","This Space is where that work is shared in the open: the programs, the training, the answers and the conversation."],"buttonLabel":"Our story","buttonHref":"/spaces/hq/about","secondaryLabel":"Ask the community","secondaryHref":"/spaces/hq/community","image":"/brand/frequency/photos/gathering-03.jpg","alt":"People gathered on rugs and cushions in a leafy garden","quote":"The structure exists to serve the circle.","quoteBy":"Daniel Tyack · Founder","register":"auto"}},{"type":"SpacePractices","props":{"id":"fh-home-journeys-1c","eyebrow":"Learn here","heading":"Courses to start","practicesHeading":"Practices","journeysHeading":"Courses","only":""}},{"type":"NewWorldProcess","props":{"id":"fh-home-path-1d","index":"03","eyebrow":"Host training","title":"From guest to *host.*","lede":"","rows":[{"icon":"calendar","title":"Learn","body":"Take Host Foundations, free and self-paced. Four short weeks on the PULSE rhythm."},{"icon":"heart","title":"Learn to care","body":"Take Safe and Well Held: agreements, consent and what to do when something comes up."},{"icon":"users","title":"Co-host","body":"Run two circles beside a trained host. Lead one beat, then two, then the whole night."},{"icon":"award","title":"Host","body":"Open your own circle with a mentor on call, then join the monthly Host Circle."}],"register":"auto"}},{"type":"NewWorldGallery","props":{"id":"fh-home-gallery-1e","index":"04","eyebrow":"Real circles","title":"Rooms people *come back to.*","lede":"Photos from Frequency gatherings.","images":[{"image":"/brand/frequency/photos/gathering-04.jpg","alt":"A circle seated on a lawn with arms stretched wide"},{"image":"/brand/frequency/photos/gathering-12.jpg","alt":"A tight group hugging and laughing on a seaside deck"},{"image":"/brand/frequency/photos/day-parachute-play.jpg","alt":"People holding a rainbow parachute on a clifftop lawn"},{"image":"/brand/frequency/photos/gathering-14.jpg","alt":"A circle on mats around a gong at the water"},{"image":"/brand/frequency/photos/gathering-13.jpg","alt":"A group moving together on the beach at golden hour"}],"register":"auto"}},{"type":"NewWorldFaq","props":{"id":"fh-home-faq-1f","index":"05","eyebrow":"Questions","title":"Good to *know.*","lede":"Anything else, ask. A real person answers.","phone":"","email":"hello@frequencylocal.com","hours":"","areasLabel":"","areas":[],"rows":[{"question":"What is this Space?","answer":"The Frequency team''s own Space: our programs, host training, Creator Lab, the help desk and a community forum, in one place. Follow it to hear what''s new."},{"question":"How do I get help with my account?","answer":"Open a help ticket from the help desk. A real person reads every one, and you can follow the reply from your tickets."},{"question":"Do I need experience to host?","answer":"No. Most Frequency hosts started as guests. Host Foundations and the apprenticeship take you from your first seat in the circle to running your own."},{"question":"Can my organization train its own hosts here?","answer":"Yes. The courses and the PULSE rhythm are built so partner organizations and volunteers can use them for their own in-person and online groups."},{"question":"Where do I ask other members a question?","answer":"In the community forum. Post a question, share what worked, or say hello. Hosts and the team read it too."}],"register":"auto"}},{"type":"NewWorldCloser","props":{"id":"fh-closer-home-1g","aside":"Generous structure. Real care. On time.","title":"Pick a door. *Come in.*","primaryLabel":"Ask the community","primaryHref":"/spaces/hq/community","secondaryLabel":"Get help","secondaryHref":"/support","note":"","register":"auto"}}]},"seo":{"title":"Frequency","description":"Frequency: programs, free host training, Creator Lab, a help desk and a community forum."},"comments":[]},{"slug":"programs","label":"Programs","doc":{"root":{"props":{}},"content":[{"type":"NewWorldPageHead","props":{"id":"fh-programs-head-1h","index":"","eyebrow":"Frequency Programs","title":"Show up. *Come back.*","lede":"Frequency Programs are the structured ways to take part: The Quest, Circles, local events and host training. Start with one.","register":"auto"}},{"type":"NewWorldWayRows","props":{"id":"fh-programs-rows-1i","costLabel":"For","whenLabel":"Rhythm","buttonLabel":"Start","buttonHref":"/circles","secondaryLabel":"Questions","secondaryHref":"/spaces/hq/help","rows":[{"icon":"award","tags":"Program","name":"The Quest","body":"Daily practices and Journeys you take with your Circle, across the four Pillars. Show up, earn Zaps and Gems, and climb the season.","price":"Every member","when":"Daily","image":"/brand/frequency/photos/gathering-13.jpg","alt":"A group moving together on the beach at golden hour","buttonLabel":"How The Quest works","href":"/help/the-quest"},{"icon":"users","tags":"Program","name":"Circles","body":"Small groups of 12 to 18 people who meet at the same time in the same place, on the PULSE rhythm.","price":"Every member","when":"Weekly or every other week","image":"/brand/frequency/photos/gathering-04.jpg","alt":"A circle seated on a lawn with arms stretched wide","buttonLabel":"Find a Circle","href":"/circles"},{"icon":"calendar","tags":"Program","name":"What''s happening","body":"Local events from Circles and Spaces near you. RSVP, add it to your calendar, bring someone.","price":"Everyone","when":"Any week","image":"/brand/frequency/photos/day-parachute-play.jpg","alt":"People holding a rainbow parachute on a clifftop lawn","buttonLabel":"See what''s happening","href":"/events"},{"icon":"sparkle","tags":"Program","name":"Creator Lab","body":"Core training for the people who gather others. The Business of Community is a free four-week live workshop on Zoom, run several times a year; the Business plan adds Business Hours on Zoom.","price":"Anyone","when":"One week at a time","image":"/brand/frequency/photos/gathering-03.jpg","alt":"People gathered on rugs and cushions in a leafy garden","buttonLabel":"Open Creator Lab","href":"/spaces/hq/creator-lab"},{"icon":"heart","tags":"Program","name":"Host training","body":"Free courses on the PULSE rhythm, care and consent, and the three circle formats, then a co-host apprenticeship.","price":"Hosts and future hosts","when":"Self-paced","image":"/brand/frequency/photos/day-meditation-circle.jpg","alt":"A large circle of people seated on the grass by the ocean, eyes closed","buttonLabel":"Start host training","href":"/spaces/hq/creator-lab"}],"register":"auto"}},{"type":"NewWorldPromises","props":{"id":"fh-programs-pillars-1j","index":"01","eyebrow":"The Quest","title":"Four *Pillars.*","lede":"Every practice and Journey sits under one Pillar, so you build the same strengths all year in different forms.","rows":[{"icon":"sparkle","title":"Mind","body":"Calm down fast, focus, and think clearly. Practices like breathing, journaling and less scrolling."},{"icon":"heart","title":"Body","body":"Move, rest, eat and sleep like you mean it. Walks, stretching, cold water, early nights."},{"icon":"users","title":"Spirit","body":"Meaning, gratitude and time with people. Stillness, service and showing up for each other."},{"icon":"award","title":"Expression","body":"Make something and share it. The weekly Expression Challenge, alone or with your Circle."}],"register":"auto"}},{"type":"NewWorldProcess","props":{"id":"fh-programs-quest-1k","index":"02","eyebrow":"How The Quest works","title":"Small things, *every day.*","lede":"","rows":[{"icon":"calendar","title":"Pick a Journey","body":"Choose one under a Pillar. Each has a few minutes of practice a day."},{"icon":"check","title":"Practice daily","body":"Log it when you do it. Streaks build, and misses are part of it."},{"icon":"users","title":"Bring your Circle","body":"Take a Journey with your Circle and show up for each other in person."},{"icon":"award","title":"Earn as you go","body":"Zaps and Gems for showing up, a Pillar Trophy when you finish a Journey."}],"register":"auto"}},{"type":"NewWorldCloser","props":{"id":"fh-closer-programs-1l","aside":"Generous structure. Real care. On time.","title":"Start with *one.*","primaryLabel":"Find a Circle","primaryHref":"/circles","secondaryLabel":"See what''s happening","secondaryHref":"/events","note":"","register":"auto"}}]},"seo":{"title":"Programs · Frequency","description":"Frequency Programs: The Quest, Circles, local events and host training."},"comments":[]},{"slug":"creator-lab","label":"Creator Lab","doc":{"root":{"props":{}},"content":[{"type":"NewWorldPageHead","props":{"id":"fh-lib-head-2c","index":"","eyebrow":"Creator Lab","title":"Courses for the people who *gather others.*","lede":"Free courses in two tracks: hosting the room, and running the community behind it. Start anywhere. Every course ends with you doing it for real.","register":"auto"}},{"type":"NewWorldPromises","props":{"id":"fh-lib-tracks-2d","index":"01","eyebrow":"The library","title":"Two *tracks.*","lede":"Each course is free. The Business plan adds a weekly room on Zoom.","rows":[{"icon":"heart","title":"Hosting","body":"The PULSE rhythm, care and consent, the three circle formats, and an apprenticeship beside a trained host."},{"icon":"sparkle","title":"Business and leadership","body":"The Business of Community: four simple meetings on PULSE that bring people back, and keep you going."}],"register":"auto"}},{"type":"NewWorldWayRows","props":{"id":"fh-lib-rows-2e","costLabel":"Cost","whenLabel":"Length","buttonLabel":"Start a course","buttonHref":"/spaces/hq/business-of-community","secondaryLabel":"Questions","secondaryHref":"/spaces/hq/help","rows":[{"icon":"calendar","tags":"Business · 4 weeks","name":"The Business of Community","body":"Frequency’s free live workshop. Four 90-minute sessions on Zoom, all on PULSE: the weekly sit-down, the opening, the full gathering and the money hour. Short lessons to read before each one.","price":"Free","when":"4 weeks","image":"/brand/frequency/photos/gathering-04.jpg","alt":"A circle seated on a lawn with arms stretched wide","buttonLabel":"See the workshop","href":"/spaces/hq/business-of-community"},{"icon":"users","tags":"Business · January Run","name":"The January Run","body":"Everyone in the launch Run, together. A thread to share what you tried between sessions, and someone noticing when you don’t show. Thursdays Jan 7, 14, 21 and 28.","price":"Free","when":"Starts January 7","image":"/brand/frequency/photos/gathering-12.jpg","alt":"A tight group hugging and laughing on a seaside deck","buttonLabel":"Join the Run","href":"/circles/business-of-community-january-2027"},{"icon":"message","tags":"Business · Zoom","name":"Business Hours","body":"Same hour every week, run on PULSE. Bring one number and one stuck thing. Last week’s commitments read back, one hot seat, and a new commitment each.","price":"Business plan","when":"Wednesdays · 10 AM Pacific","image":"/sites/new-world/photos/cafe-table.webp","alt":"Three people talking at a small table in a cafe","buttonLabel":"See the Circle","href":"/circles/business-hours"},{"icon":"calendar","tags":"Hosting · Online","name":"Host Foundations","body":"Four short weeks on the craft every Frequency host shares: why we gather, the PULSE rhythm, setting the room, and running your first circle.","price":"Free","when":"4 parts","image":"/brand/frequency/photos/day-meditation-circle.jpg","alt":"","buttonLabel":"Start the course","href":"/journeys/host-foundations"},{"icon":"heart","tags":"Hosting · Online","name":"Safe and Well Held","body":"Agreements, consent and care: how to keep a room safe enough to be honest, and what to do when something comes up.","price":"Free","when":"4 parts","image":"/brand/frequency/photos/gathering-12.jpg","alt":"","buttonLabel":"Start the course","href":"/journeys/safe-and-well-held"},{"icon":"users","tags":"Hosting · Online","name":"The Three Circle Formats","body":"Open, Community and Focus Circles: what each one is for, what the host does, and how to choose.","price":"Free","when":"4 parts","image":"/brand/frequency/photos/gathering-03.jpg","alt":"","buttonLabel":"Start the course","href":"/journeys/circle-formats"},{"icon":"award","tags":"Hosting · In person","name":"Co-host Apprenticeship","body":"Learn by doing: shadow a trained host, co-lead two circles, then host your own with a mentor on call.","price":"Ask us","when":"Three circles","image":"/brand/frequency/photos/gathering-04.jpg","alt":"","buttonLabel":"Ask about a mentor","href":"/journeys/co-host-apprenticeship"}],"register":"auto"}},{"type":"NewWorldProcess","props":{"id":"fh-pulse-beats-1p","index":"02","eyebrow":"The PULSE rhythm · for everyone","title":"What each beat *is.*","lede":"","rows":[{"icon":"heart","title":"P · Presence","body":"Arrive. A few slow breaths, feet on the floor, phones away. The host sets the tone by going first."},{"icon":"users","title":"U · Unite","body":"A check-in round. Each person says how they''re arriving, and everyone else listens without replying."},{"icon":"award","title":"L · Lead","body":"Tonight''s practice: a teaching, a movement, a conversation or a skill. The part that changes from week to week."},{"icon":"check","title":"S · Settle","body":"Quiet integration. Rest, journal or sit with what came up before anyone has to talk about it."},{"icon":"message","title":"E · Exhale","body":"Close together. One word or one line each, a thank you, and a clear end."}],"register":"auto"}},{"type":"NewWorldFirstVisit","props":{"id":"fh-pulse-host-1q","index":"03","eyebrow":"The PULSE rhythm · for the host","title":"What you *do.*","lede":"A 90-minute night, beat by beat.","note":"Shorter night? Trim Lead first. Never skip Exhale.","rows":[{"title":"Presence · 10 min","body":"Start on time. Welcome people by name. Name the purpose of tonight in one sentence."},{"title":"Unite · 20 min","body":"Read the agreements. Ask one question everyone can answer. Keep it lean so everyone gets a turn."},{"title":"Lead · 35 min","body":"Give clear steps, an invitation and an opt-out. Watch the room more than your notes."},{"title":"Settle · 15 min","body":"Lower the pace. Offer a simple prompt. Let silence do some of the work."},{"title":"Exhale · 10 min","body":"End on time. Say what happens next and how people can reach you."}],"register":"auto"}},{"type":"NewWorldPromises","props":{"id":"fh-training-formats-1r","index":"04","eyebrow":"One rhythm","title":"Three *formats.*","lede":"Every circle runs on PULSE. The format decides how much you teach and how big the room gets.","rows":[{"icon":"users","title":"Open Circle · 12 to 18 people","body":"The host keeps the room, with no teaching agenda. People come to be heard and to hear each other. You open and close, keep the agreements and the time, and pass the turn. You speak least."},{"icon":"heart","title":"Community Circle · 12 to 18 people","body":"A hosted circle around one shared theme: moon circles, men''s and women''s circles, grief, new parents, sharing circles. You choose the theme and the question for the round, and keep the circle on it."},{"icon":"award","title":"Focus Circle · Up to 50 people","body":"The host teaches a modality: breathwork, sound, movement, a skill. The PULSE rhythm wraps the teaching so the room still feels like a circle. You teach in the Lead beat, and the four beats around it keep it personal and safe."}],"register":"auto"}},{"type":"NewWorldPromises","props":{"id":"fh-training-agreements-1s","index":"05","eyebrow":"Read at every circle","title":"Six *agreements.*","lede":"","rows":[{"icon":"check","title":"Every practice is an invitation","body":"Join in, go gently, watch, or pass. No one needs a reason."},{"icon":"heart","title":"What is shared stays here","body":"Take the lessons home. Leave the stories and the names in the room."},{"icon":"users","title":"Speak for yourself","body":"Use I. Speak from your own life, not about anyone else''s."},{"icon":"message","title":"No fixing","body":"Listen without advising, correcting or rescuing. Ask an honest question, or simply say thank you."},{"icon":"calendar","title":"Start and end on time","body":"A clear start and a clear end are a kindness. People can plan around you."},{"icon":"award","title":"Ask before touch","body":"No touch without a clear yes, every time. Nothing sexual happens in a circle."}],"register":"auto"}},{"type":"NewWorldFirstVisit","props":{"id":"fh-training-care-1t","index":"06","eyebrow":"When something comes up","title":"Safe enough *to be honest.*","lede":"Our training follows the six principles of a trauma-informed approach: safety, trust and transparency, peer support, collaboration, choice and voice, and culture and context.","note":"A Frequency circle is practice and community, not therapy or crisis care. In the US, call or text 988 for the Suicide and Crisis Lifeline. If anyone is in immediate danger, call emergency services.","rows":[{"title":"Strong feelings","body":"Slow down. Let the person finish, thank them, and offer a breath for the whole circle. Tears aren''t an emergency."},{"title":"A disclosure","body":"Thank them, don''t press for details in the circle, and speak privately afterwards. Share the local crisis line."},{"title":"One voice filling the room","body":"Use the talking piece. Set a time per share before the round starts. Invite someone who hasn’t spoken yet."},{"title":"After a hard night","body":"Debrief with your co-host or mentor within a day. Hosting is a team practice."}],"register":"auto"}},{"type":"NewWorldCloser","props":{"id":"fh-closer-creator-lab-2f","aside":"Generous structure. Real care. On time.","title":"Start with *one course.*","primaryLabel":"The Business of Community","primaryHref":"/spaces/hq/business-of-community","secondaryLabel":"Start Host Foundations","secondaryHref":"/journeys/host-foundations","note":"","register":"auto"}}]},"seo":{"title":"Creator Lab · Frequency","description":"Creator Lab: free courses for the people who gather others. Hosting on the PULSE rhythm, and The Business of Community."},"comments":[]},{"slug":"business-of-community","label":"Business of Community","doc":{"root":{"props":{}},"content":[{"type":"PhotoHero","props":{"id":"boc-hero-0","variant":"image","display":"beside","height":"medium","scrim":"light","image":"/sites/new-world/photos/beach-joy.webp","alt":"Friends laughing together on a beach at golden hour","eyebrow":"Live workshop · Free","title":"People showed up once. Here’s how they come back.","accentWord":"Here’s how they come back.","subtitle":"The Business of Community is Frequency’s free four-week live workshop for anyone who gathers people. Four simple meetings you can run, all on the PULSE rhythm. It assumes you’re starting from scratch.","actionPrimaryLabel":"Save your seat","actionPrimaryHref":"/events/business-of-community-pilot-session-1","actionSecondaryLabel":"Join the January Run","actionSecondaryHref":"/circles/business-of-community-january-2027","note":"Thursdays, January 7 to 28 · 10 to 11:30 AM Pacific · on Zoom"}},{"type":"Zigzag","props":{"id":"boc-idea-1","image":"/sites/new-world/photos/circle-sunrise.webp","alt":"A small group sitting in a circle outdoors at sunrise","mediaSide":"right","background":"canvas","eyebrow":"The one idea","title":"Frequency. The how-often kind.","accentWord":"The how-often kind.","body":"lead","lead":"Most people who gather others count heads. How many came. How full it looked.<br><br>A community lives on a different number: how many came back. A small room where people return is healthier than a big room you never see again. That number runs through all four weeks.","items":[],"quoteBy":"","ctaLabel":"","ctaHref":""}},{"type":"CardGrid","props":{"id":"boc-weeks-2","role":"step","columns":2,"eyebrow":"The four weeks","title":"Four meetings you can run.","accentWord":"you can run.","cards":[{"title":"Jan 7 · The weekly sit-down","body":"A weekly 30-minute meeting with yourself that keeps you from carrying everything at once."},{"title":"Jan 14 · The opening","body":"An opening you can run every time: your purpose in one line, three agreements read aloud, and a check-in round."},{"title":"Jan 21 · The full gathering","body":"A one-page run sheet for a 90-minute gathering, and a ten-minute habit the next day to see who came back."},{"title":"Jan 28 · The money hour","body":"Your break-even number, one price you can say without flinching, and a monthly hour to keep both honest."}],"browseLabel":"","browseHref":""}},{"type":"Zigzag","props":{"id":"boc-week-3","image":"/sites/new-world/photos/workshop-table.webp","alt":"Adults and kids making crafts around a long table in a workshop room","mediaSide":"left","background":"accent-wash","eyebrow":"How each week works","title":"Read it. Practice it. Run it.","accentWord":"Run it.","body":"list","lead":"","items":[{"text":"Before Thursday, about 15 minutes: a short overview and one lesson."},{"text":"Thursday, 90 minutes live on Zoom, on PULSE: a story, check-ins in small groups, the meeting and a practice run, a moment to steady, and one commitment said out loud."},{"text":"After: run the meeting once with your own people, fill in your one page, and post a three-line report back to your Run."}],"quoteBy":"","ctaLabel":"Save your seat","ctaHref":"/events/business-of-community-pilot-session-1"}},{"type":"CardGrid","props":{"id":"boc-guides-4","role":"media","columns":2,"eyebrow":"Your guides","title":"Hosted by Frequency. Led by Daniel and Feargal.","accentWord":"Led by Daniel and Feargal.","cards":[{"image":"/brand/frequency/photos/guide-daniel-tyack.jpg","alt":"Daniel Tyack","title":"Daniel Tyack","body":"Founder of Frequency. Daniel has spent years building and leading rooms, from music to men’s work to ceremony, and created PULSE, the rhythm the workshop runs on."},{"image":"/brand/frequency/photos/guide-feargal-walsh.jpg","alt":"Feargal Walsh","title":"Feargal Walsh","body":"Leads technology and member experience at Frequency. Feargal turns the systems organizers need into tools that are simple to run week after week."}],"browseLabel":"","browseHref":""}},{"type":"CardGrid","props":{"id":"boc-ways-5","role":"feature","columns":2,"eyebrow":"Two ways in","title":"Four weeks together, then every week.","accentWord":"then every week.","cards":[{"icon":"◎","title":"The live workshop","body":"Free for anyone, Space or not. Four Thursdays on Zoom, 10 to 11:30 AM Pacific, several times a year. The launch Run meets January 7 to 28.","button":{"label":"Save your seat","href":"/events/business-of-community-pilot-session-1"}},{"icon":"↗","title":"Business Hours","body":"For Spaces on the Business plan. Wednesday mornings at 10 AM Pacific on Zoom, run on PULSE in a members-only Circle. Bring one number and one stuck thing.","button":{"label":"See the Circle","href":"/circles/business-hours"}}],"browseLabel":"See the Business plan","browseHref":"/pricing"}},{"type":"Zigzag","props":{"id":"boc-finish-6","image":"/sites/new-world/photos/fire-circle.webp","alt":"People sitting around a fire at dusk","mediaSide":"right","background":"canvas","eyebrow":"Two ways to finish","title":"Attended or Certified.","accentWord":"Certified.","body":"list","lead":"","items":[{"text":"Attended: come to all four live sessions."},{"text":"Certified: send in your Community Book, your four pages filled in from real gatherings. Review is free for Community Books submitted by February 28, 2027, then comes with the Business plan."},{"text":"Certified is a certificate of completion and competency from Frequency. It is not an accredited certification."}],"quoteBy":"","ctaLabel":"","ctaHref":""}},{"type":"EditorialSection","props":{"id":"boc-faq-7","eyebrow":"Questions","title":"Good to know.","accentWord":"know.","kicker":"Anything else, ask. A person on the Frequency team answers.","body":"faq","surface":"open","lead":"","stats":[],"faqs":[{"q":"What does it cost?","a":"Nothing. The workshop is free for anyone. Certified review is free for Community Books submitted by February 28, 2027, then comes with the Business plan."},{"q":"When is the next workshop?","a":"The launch Run meets Thursdays, 10 to 11:30 AM Pacific, on Zoom: January 7, 14, 21 and 28, 2027, the month Frequency launches. Anyone can join. Save your seat on the Week 1 event and the Zoom link comes to you. New Runs start through the year."},{"q":"How much time does it take?","a":"About three hours a week. Before Thursday, 15 minutes: a short overview and one lesson. Thursday, 90 minutes live. After, your homework: run that week’s meeting once with your own people and post a three-line report back."},{"q":"I haven’t started anything yet. Is it for me?","a":"Yes. It assumes you’re starting from scratch. If you run something already, you’ll fix the parts that wear you out."},{"q":"What is PULSE?","a":"The five-beat rhythm every Frequency gathering follows: Presence, Unite, Lead, Settle, Exhale. Every meeting in this workshop runs on it, and so does each session."},{"q":"Do I need a Space?","a":"No. Everything works on paper and a phone. If you have a Space, each week ends with an optional step to set it up there."},{"q":"What is Business Hours?","a":"A weekly hour on Zoom for Spaces on the Business plan, Wednesday mornings at 10 AM Pacific, run on PULSE in a members-only Circle. Bring one number and one stuck thing."},{"q":"Is it accredited?","a":"No. Certified is a certificate of completion and competency from Frequency, not an accredited certification."}]}},{"type":"AccentBeat","props":{"id":"boc-closer-8","mode":"cta","background":"accent-wash","image":"","alt":"","eyebrow":"Free · Four weeks · Live on Zoom","title":"Keep the room. Keep yourself.","accentWord":"Keep yourself.","body":"The launch Run starts Thursday, January 7.","quoteBy":"","ctaLabel":"Save your seat","ctaHref":"/events/business-of-community-pilot-session-1","ctaSecondaryLabel":"Ask a question","ctaSecondaryHref":"/spaces/hq/help"}}]},"seo":{"title":"The Business of Community 101 · Frequency","description":"Frequency’s free four-week live business workshop for anyone who gathers people. Four simple meetings on the PULSE rhythm, live on Zoom. Starts January 7, 2027."},"comments":[]},{"slug":"help","label":"Help desk","doc":{"root":{"props":{}},"content":[{"type":"NewWorldPageHead","props":{"id":"fh-help-head-22","index":"","eyebrow":"Help desk","title":"Ask. *A person answers.*","lede":"Open a help ticket, browse the help center, or ask the community. Every ticket is read by a real person on the Frequency team.","register":"auto"}},{"type":"NewWorldWayRows","props":{"id":"fh-help-rows-23","costLabel":"Cost","whenLabel":"Best for","buttonLabel":"Open a help ticket","buttonHref":"/support","secondaryLabel":"Common questions","secondaryHref":"#faq","rows":[{"icon":"message","tags":"Help desk","name":"Open a help ticket","body":"Tell us what happened. Follow every reply from your tickets.","price":"Free","when":"Your account, billing, bugs","image":"/sites/new-world/photos/cafe-table.webp","alt":"Three people talking at a small table in a cafe","buttonLabel":"Open a ticket","href":"/support"},{"icon":"check","tags":"Help center","name":"Browse the help center","body":"Plain answers on Circles, events, Spaces, The Quest and membership.","price":"Free","when":"How-to questions","image":"/sites/new-world/photos/garden-picnic.webp","alt":"People gathered on rugs and cushions in a leafy backyard garden","buttonLabel":"Open the help center","href":"/help"},{"icon":"users","tags":"Forum","name":"Ask the community","body":"Post a question or an idea. Members, hosts and the team answer.","price":"Free","when":"Ideas and how others do it","image":"/brand/frequency/photos/gathering-12.jpg","alt":"A tight group hugging and laughing on a seaside deck","buttonLabel":"Go to the forum","href":"/spaces/hq/community"},{"icon":"heart","tags":"Safety","name":"Report a safety concern","body":"Reporting, blocking and how moderation works. In an emergency, call emergency services first.","price":"Free","when":"Anything that feels unsafe","image":"/sites/new-world/photos/fire-circle.webp","alt":"People sitting quietly around a fire pit in the evening","buttonLabel":"Safety and reporting","href":"/help/safety"}],"register":"auto"}},{"type":"NewWorldPosts","props":{"id":"fh-help-center-24","index":"01","eyebrow":"Help center","title":"Find it *fast.*","lede":"Seven topics, written in plain words.","buttonLabel":"Open the help center","buttonHref":"/help","rows":[{"kind":"Start here","title":"Getting started: what Frequency is and how to find your people","meta":"","href":"/help/getting-started"},{"kind":"Groups","title":"Circles and events: how gatherings work","meta":"","href":"/help/groups"},{"kind":"Hosting","title":"Leading a Circle: start one, run the first night, keep it going","meta":"","href":"/help/leading"},{"kind":"Spaces","title":"Running a Space: the tools a Space gives you","meta":"","href":"/help/spaces"},{"kind":"The Quest","title":"Zaps, Gems, ranks and rewards","meta":"","href":"/help/the-quest"},{"kind":"Membership","title":"What''s free and what Crew adds","meta":"","href":"/help/membership"},{"kind":"Safety","title":"Reporting, blocking and how moderation works","meta":"","href":"/help/safety"}],"register":"auto"}},{"type":"NewWorldFaq","props":{"id":"fh-help-faq-25","index":"02","eyebrow":"Questions","title":"Good to *know.*","lede":"Still stuck? Open a ticket or email us.","phone":"","email":"hello@frequencylocal.com","hours":"","areasLabel":"","areas":[],"rows":[{"question":"How do I open a help ticket?","answer":"Go to Help and support, describe what happened, and send it. You can follow every reply from your tickets on the same page."},{"question":"Something feels unsafe. What do I do?","answer":"Use Report on the post, profile or event, or open a ticket marked safety. If anyone is in immediate danger, call emergency services first."},{"question":"I have a billing question.","answer":"Open a ticket and choose billing. Include the email on your account so we can find it quickly."},{"question":"How do I start a Space for my business or group?","answer":"Read Running a Space in the help center, then create one from the Spaces page. The help desk can walk you through it."},{"question":"Can I suggest a feature?","answer":"Yes, please. Post it in the community forum so others can add to it, or open a ticket if it is about your own account."}],"register":"auto"}},{"type":"NewWorldCloser","props":{"id":"fh-closer-help-26","aside":"Generous structure. Real care. On time.","title":"Still stuck? *Ask us.*","primaryLabel":"Open a help ticket","primaryHref":"/support","secondaryLabel":"Ask the community","secondaryHref":"/spaces/hq/community","note":"","register":"auto"}}]},"seo":{"title":"Help desk · Frequency","description":"Open a help ticket, browse the help center, or ask the community."},"comments":[]},{"slug":"about","label":"About","doc":{"root":{"props":{}},"content":[{"type":"NewWorldAboutHero","props":{"id":"fh-about-hero-27","eyebrow":"Our story · Frequency","title":"Build circles, *not walls.*","lead":"Frequency is a community collective that spreads town by town through local hosts. This Space is where the team shares the programs, the training, the answers and the conversation in the open.","chips":[{"icon":"check","text":"Free to start"},{"icon":"users","text":"Run with its members"},{"icon":"heart","text":"Care designed in"}],"primaryLabel":"Explore programs","primaryHref":"/spaces/hq/programs","secondaryLabel":"Ask the community","secondaryHref":"/spaces/hq/community","image":"/sites/new-world/photos/circle-sunrise.webp","alt":"A wide circle of people seated on a plaza at sunrise","name":"Daniel Tyack","role":"Founder","register":"auto"}},{"type":"NewWorldLongStory","props":{"id":"fh-about-roots-28","index":"01","eyebrow":"Where this comes from","title":"Old practices, *plain words.*","paragraphs":["Sitting in a circle and taking turns to speak is one of the oldest ways people have gathered. We did not invent it. We gave it a rhythm, PULSE, that a new host can learn in a week and a returning guest can trust.","Our host training draws on a few sources worth reading in full. The Way of Council, as taught by Jack Zimmerman and Virginia Coyle, gives us the talking piece and its intentions. Parker Palmer and the Center for Courage and Renewal give us touchstones for trustworthy space, like no fixing and honest, open questions. Priya Parker gives us generous authority: a host who protects, connects and equalizes the room. SAMHSA gives us the six principles of a trauma-informed approach.","Everything is written in plain words, because a host should be able to read an agreement aloud without explaining it."],"register":"auto"}},{"type":"NewWorldQuote","props":{"id":"fh-about-quote-29","label":"In Daniel’s words","quote":"The structure exists to serve the circle. The circle *governs the structure.*","by":"Daniel Tyack · Founder","register":"auto"}},{"type":"NewWorldTeam","props":{"id":"fh-about-team-2a","index":"02","eyebrow":"The team","title":"Who *runs this.*","lede":"","note":"Trained hosts join this list as they become mentors.","rows":[{"name":"Daniel Tyack","role":"Founder · The Janitor","image":"/brand/frequency/photos/daniel-tyack.jpg","alt":"Daniel Tyack smiling"}],"register":"auto"}},{"type":"NewWorldCloser","props":{"id":"fh-closer-about-2b","aside":"Generous structure. Real care. On time.","title":"Pick a door. *Come in.*","primaryLabel":"Ask the community","primaryHref":"/spaces/hq/community","secondaryLabel":"Get help","secondaryHref":"/support","note":"","register":"auto"}}]},"seo":{"title":"About · Frequency","description":"Frequency is a community collective. Build circles, not walls."},"comments":[]}]}}]},"websitePublished":true,"profileData":{"about":"This is the Frequency team''s own Space: the home base for everyone building Frequency. Find our programs, take free host training on the PULSE rhythm, learn to run your community in Creator Lab, get help from a real person, and ask the community in the forum.","kind":"business","categoryLabel":"Community collective","email":"hello@frequencylocal.com","website":"https://frequencylocal.com","socials":[{"platform":"website","url":"https://frequencylocal.com"},{"platform":"instagram","url":"https://www.instagram.com/frequencylocal"},{"platform":"tiktok","url":"https://www.tiktok.com/@frequencylocal"},{"platform":"youtube","url":"https://www.youtube.com/@frequencylocal"}],"offerings":[{"title":"The Quest","blurb":"Daily practices and Journeys you take with your Circle, across the four Pillars. Show up, earn Zaps and Gems, and climb the season."},{"title":"Circles","blurb":"Small groups of 12 to 18 people who meet at the same time in the same place, on the PULSE rhythm."},{"title":"What''s happening","blurb":"Local events from Circles and Spaces near you. RSVP, add it to your calendar, bring someone."},{"title":"Creator Lab","blurb":"Core training for the people who gather others. The Business of Community is a free four-week live workshop on Zoom, run several times a year; the Business plan adds Business Hours on Zoom."},{"title":"Host training","blurb":"Free courses on the PULSE rhythm, care and consent, and the three circle formats, then a co-host apprenticeship."},{"title":"Help desk","blurb":"Open a help ticket and a real person on the Frequency team answers."}]},"profilePublished":true}'::jsonb)
on conflict (slug) do update set name = excluded.name, status = 'active', network_connected = true, visibility = 'network', plan = excluded.plan, is_comped = excluded.is_comped, limits_waived = excluded.limits_waived, brand_name = excluded.brand_name, brand_accent = excluded.brand_accent, tagline = excluded.tagline, about = excluded.about, time_zone = excluded.time_zone, brand_logo_url = excluded.brand_logo_url, cover_image_url = excluded.cover_image_url,
  preferences = coalesce(spaces.preferences, '{}'::jsonb) || (excluded.preferences - array['pageDocs', 'pages', 'profileLayout', 'websiteEditor', 'websitePublished']::text[]) || (select coalesce(jsonb_object_agg(k, v), '{}'::jsonb) from jsonb_each(excluded.preferences) e(k, v) where k = any(array['pageDocs', 'pages', 'profileLayout', 'websiteEditor', 'websitePublished']::text[]) and not (coalesce(spaces.preferences, '{}'::jsonb) ? k)), updated_at = now()
where spaces.owner_profile_id = '78d47bae-c4c8-4d1c-80a0-ac69aaf98ef8';

-- 2. Members: the owner and @danieltyack, both Space admins (provision.ts seats the owner as admin).
insert into space_members (space_id, profile_id, role, status)
select s.id, m.pid, 'admin', 'active' from spaces s, (values ('78d47bae-c4c8-4d1c-80a0-ac69aaf98ef8'::uuid), ('c1d40f58-318b-4c7b-a331-21788d632fc9'::uuid)) m(pid) where s.slug = 'hq'
on conflict (space_id, profile_id) do update set role = 'admin', status = 'active';

-- 2b. FAQ rows the module engine's FAQ block reads (space_faqs).
insert into space_faqs (id, space_id, question, answer, position) values
('abeb1f3a-8943-265d-9c11-ffe365045e95', (select id from spaces where slug = 'hq'), 'What is this Space?', 'The Frequency team''s own Space: our programs, host training, Creator Lab, the help desk and a community forum, in one place. Follow it to hear what''s new.', 0),
('be56d682-ac4c-8168-99c4-c883d690067b', (select id from spaces where slug = 'hq'), 'How do I get help with my account?', 'Open a help ticket from the help desk. A real person reads every one, and you can follow the reply from your tickets.', 1),
('cf95aba8-c126-e432-a879-f40b097322b2', (select id from spaces where slug = 'hq'), 'Do I need experience to host?', 'No. Most Frequency hosts started as guests. Host Foundations and the apprenticeship take you from your first seat in the circle to running your own.', 2),
('1c63a3b5-1df3-fbd6-9dd3-413c72b0fe47', (select id from spaces where slug = 'hq'), 'Can my organization train its own hosts here?', 'Yes. The courses and the PULSE rhythm are built so partner organizations and volunteers can use them for their own in-person and online groups.', 3),
('e972db2c-19ab-6dd9-433a-a5ecb06c2cbb', (select id from spaces where slug = 'hq'), 'Where do I ask other members a question?', 'In the community forum. Post a question, share what worked, or say hello. Hosts and the team read it too.', 4),
('82e33802-cc03-a63a-5aab-1f45ba0503a4', (select id from spaces where slug = 'hq'), 'How do I open a help ticket?', 'Go to Help and support, describe what happened, and send it. You can follow every reply from your tickets on the same page.', 5),
('7ab592bf-ac08-d812-0e77-f9a6b892af75', (select id from spaces where slug = 'hq'), 'Something feels unsafe. What do I do?', 'Use Report on the post, profile or event, or open a ticket marked safety. If anyone is in immediate danger, call emergency services first.', 6),
('05b94679-e8d6-5bb1-d3c9-f5be23c5a527', (select id from spaces where slug = 'hq'), 'I have a billing question.', 'Open a ticket and choose billing. Include the email on your account so we can find it quickly.', 7),
('e823291d-421c-0be8-b8aa-ac35f8d48e7e', (select id from spaces where slug = 'hq'), 'How do I start a Space for my business or group?', 'Read Running a Space in the help center, then create one from the Spaces page. The help desk can walk you through it.', 8),
('2d74cdb1-c653-e809-ba8d-c8e8269ae343', (select id from spaces where slug = 'hq'), 'Can I suggest a feature?', 'Yes, please. Post it in the community forum so others can add to it, or open a ticket if it is about your own account.', 9)
on conflict (id) do update set question = excluded.question, answer = excluded.answer, position = excluded.position, updated_at = now();

-- 3. The training Journeys (journey_plans, scripts/seed-wildheart.mts shape), published on the Space.
insert into journey_plans (id, slug, title, summary, intro, author_id, space_id, visibility, status, published_at, category, difficulty, tags, daily_minutes, enroll_cap, meeting, ongoing, drip_interval_days, sequential, cover_image, official)
values ('b683afb5-5ff3-372d-e081-7952ea0ed28b', 'host-foundations', 'Host Foundations', 'Four short weeks on the craft every Frequency host shares: why we gather, the PULSE rhythm, setting the room, and running your first circle.', 'Hosting is a learnable skill. You don''t need to be a teacher or a therapist. You need a clear purpose, a rhythm people can trust, and the nerve to start and end on time.

This course walks you through the PULSE rhythm every Frequency gathering follows: Presence, Unite, Lead, Settle, Exhale. One theme a week, a short practice to try, and a reflection to bring to your first co-hosted circle.', '78d47bae-c4c8-4d1c-80a0-ac69aaf98ef8', (select id from spaces where slug = 'hq'), 'public', 'approved', now(), 'Hosting', 'gentle', array['hosting', 'facilitation', 'PULSE', 'circles', 'host training']::text[], 15, null, '{"format":"online","schedule":"Self-paced","timezone":"America/Los_Angeles","location":null,"link":null,"notes":null,"eventId":null,"gathering":null}'::jsonb, false, 0, true, '/brand/frequency/photos/day-meditation-circle.jpg', true)
on conflict (slug) do update set title = excluded.title, summary = excluded.summary, intro = excluded.intro, space_id = excluded.space_id, visibility = excluded.visibility, status = excluded.status, published_at = coalesce(journey_plans.published_at, excluded.published_at), category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, daily_minutes = excluded.daily_minutes, meeting = excluded.meeting, sequential = excluded.sequential, cover_image = excluded.cover_image, official = excluded.official, updated_at = now()
where journey_plans.author_id = '78d47bae-c4c8-4d1c-80a0-ac69aaf98ef8';
insert into journey_plans (id, slug, title, summary, intro, author_id, space_id, visibility, status, published_at, category, difficulty, tags, daily_minutes, enroll_cap, meeting, ongoing, drip_interval_days, sequential, cover_image, official)
values ('3bcd3261-293f-ae45-a34e-ce51c49234e4', 'safe-and-well-held', 'Safe and Well Held', 'Agreements, consent and care: how to keep a room safe enough to be honest, and what to do when something comes up.', 'A circle only feels free when it feels safe. Safety isn''t left to a host''s instinct. It''s designed in: clear agreements, real choice, and a plan for the moment someone needs more than the room can give.

This course is grounded in the six principles of a trauma-informed approach. It won''t make you a therapist, and it isn''t meant to. It will help you host in a way that does no harm and knows when to refer.', '78d47bae-c4c8-4d1c-80a0-ac69aaf98ef8', (select id from spaces where slug = 'hq'), 'public', 'approved', now(), 'Hosting', 'standard', array['hosting', 'consent', 'safety', 'trauma-informed', 'host training']::text[], 15, null, '{"format":"online","schedule":"Self-paced","timezone":"America/Los_Angeles","location":null,"link":null,"notes":null,"eventId":null,"gathering":null}'::jsonb, false, 0, true, '/brand/frequency/photos/gathering-12.jpg', true)
