values ('19a74831-bf25-9b34-0adc-f2c1838ce635', 'co-host-apprenticeship', 'Co-host Apprenticeship', 'Learn by doing: shadow a trained host, co-lead two circles, then host your own with a mentor on call.', 'Nobody learns to host from reading. The apprenticeship pairs you with a trained Frequency host. You''ll watch one circle, lead part of the next, lead most of the one after, and then host your own while your mentor is a call away.', '78d47bae-c4c8-4d1c-80a0-ac69aaf98ef8', (select id from spaces where slug = 'hq'), 'public', 'approved', now(), 'Hosting', 'standard', array['hosting', 'mentorship', 'apprenticeship', 'host training']::text[], 10, null, '{"format":"in_person","schedule":"Three circles with a trained host","timezone":"America/Los_Angeles","location":null,"link":null,"notes":null,"eventId":null,"gathering":null}'::jsonb, false, 0, true, '/brand/frequency/photos/gathering-04.jpg', true)
